"Four screens. One swipe.": "Cuatro pantallas. Un deslizamiento.",
"Review is your weekly question, List is everything you've said yes to, Shed is your total and your machines, You is settings. <strong>Switch on swiping in You and flick between them.</strong>": "Revisar es tu pregunta semanal, Lista es todo a lo que dijiste sí, Soltar es tu total y tus máquinas, Tú son los ajustes. <strong>Activa el deslizamiento en Tú y pasa de una a otra.</strong>",
"A to-do list that gets shorter.": "Una lista de tareas que se acorta.",
"Every other app helps you add things. Shedly helps you let go of one. <strong>Once a week.</strong> That's the whole trick.": "Todas las demás apps te ayudan a añadir cosas. Shedly te ayuda a soltar una. <strong>Una vez a la semana.</strong> Ese es todo el truco.",
"Once a week, one question.": "Una vez a la semana, una pregunta.",
"Add anything you've said yes to: tasks, meetings, subscriptions. Put a price on it and Shedly does the sums. <strong>Yes, even that one you forgot about.</strong>": "Añade todo a lo que dijiste sí: tareas, reuniones, suscripciones. Ponle precio y Shedly hace las cuentas. <strong>Sí, incluso esa que olvidaste.</strong>",
"It notices things.": "Se da cuenta de las cosas.",
"Renewals coming up, what each use really costs, and a line when you've kept something again and again. <strong>Never a rule. Always your call.</strong>": "Renovaciones próximas, lo que cuesta de verdad cada uso y una línea cuando conservas algo una y otra vez. <strong>Nunca una norma. Siempre tu decisión.</strong>",
