"Watch the number go up.": "Mira cómo sube el número.",
"Every shed adds to your total, and to what you've freed up if it had a price. Miss a week and nothing explodes. <strong>Miss a month and we'll mention it.</strong>": "Cada cosa soltada suma a tu total y a lo que has liberado si tenía precio. Si te saltas una semana, no pasa nada. <strong>Si te saltas un mes, lo comentaremos.</strong>",
