"Shown on your weekly review. Stays on this device.": "Se muestra en tu revisión semanal. Se queda en este dispositivo.",
"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Comparte qué pantallas y botones usas y graba cómo se ven las pantallas con todo el texto oculto. Nunca se envían nombres, precios, notas ni texto escrito. Desactívalo cuando quieras.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Muestra el tiempo de hoy en el cielo. Pide tu ubicación aproximada una vez y la envía redondeada a unos 10 km a Open-Meteo para consultar el tiempo. No se envía nada más.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Activa los avisos en Tú, en Notificaciones. Elige las fechas: una semana, tres días y un día antes. <strong>Silencio después de las 21:00 y nunca más de uno al día.</strong>",
