"Everything you've said yes to, costliest and most ignored first.": "Todo a lo que dijiste sí, lo más caro y más ignorado primero.",
"Nothing yet. What are you paying attention to right now?": "Nada todavía. ¿A qué le estás prestando atención ahora mismo?",
