"Clean lines, clinical stare. Judges your spelling, quietly.": "Líneas limpias, mirada clínica. Juzga tu ortografía en silencio.",
"Lives for Monday piles. Gets loud about it.": "Vive para las pilas del lunes. Y se pone ruidosa por ello.",
