"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Cela supprime ta liste, ton historique, tes machines, ta série, ton nom, ton pays et tes réglages de cet appareil, puis relance Shedly comme à la première installation. C'est irréversible.",
