"Year in review is part of Plus. Preview Plus below.": "Le bilan annuel fait partie de Plus. Teste Plus ci-dessous.",
"Search what you've shed": "Cherche ce que tu as lâché",
"Export my data": "Exporter mes données",
"Erase everything": "Tout effacer",
"Erase your list, history and profile from this device? This can't be undone.": "Effacer ta liste, ton historique et ton profil de cet appareil ? C'est irréversible.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Ta liste est stockée sur cet appareil, plus les dates de rappel si les rappels sont activés. Exporter te donne une copie ; effacer la supprime d'ici.",
"Help test Shedly": "Aide à tester Shedly",
"Testing notes": "Notes de test",
"Read the testing notes": "Lire les notes de test",
"What we see": "Ce que nous voyons",
"What we never see": "Ce que nous ne voyons jamais",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Quels écrans et boutons tu utilises, ta série par tranches et des enregistrements dont tout le texte est masqué.",
"Item names, prices, dates, notes, your name or anything you type.": "Noms, prix, dates, notes, ton nom ou tout ce que tu saisis.",
"Thank you. You're helping us make it better.": "Merci. Tu nous aides à l'améliorer.",
"Count me in": "Je participe",
"Maybe later": "Peut-être plus tard",
"Not for me": "Pas pour moi",
"You can change this any time in You.": "Tu peux changer cela quand tu veux dans Toi.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens": "Tu fais partie des premières personnes à essayer Shedly. <strong>Partager l'usage anonyme est le moyen le plus rapide de l'améliorer.</strong> Cela nous montre quels écrans",
"Looking back": "Un regard en arrière",
"Don't ask about this one": "Ne plus demander pour celui-ci",
"Not at all": "Pas du tout",
"A bit": "Un peu",
"Yes, bring it back": "Oui, le remettre",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "Les notifications sont bloquées. Autorise-les pour Shedly dans les réglages du téléphone.",
"Couldn't turn reminders on. Try again.": "Impossible d'activer les rappels. Réessaie.",
"Reminders are on.": "Rappels activés.",
"Reminders are off.": "Rappels désactivés.",
"Turn reminders on": "Activer les rappels",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Sur iPhone, ajoute Shedly à ton écran d'accueil, puis ouvre-la depuis là.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Ce navigateur ne peut pas envoyer de rappels. Essaie Chrome sur Android ou Safari sur iPhone.",
"Item reminders": "Rappels par élément",
"Deadline reminders": "Rappels d'échéances",
"For items with a date: a week, three days and one day before.": "Pour les éléments datés : une semaine, trois jours et un jour avant.",
"Sunday evening, when this week's shed is due.": "Le dimanche soir, quand il faut lâcher quelque chose cette semaine.",
"At most once a month, for items untouched for 30 days or more.": "Au plus une fois par mois, pour les éléments intacts depuis 30 jours ou plus.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "Le dimanche après-midi, seulement avec une série de deux semaines ou plus.",
"Show item names": "Afficher les noms",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Désactivé : le rappel dit « Un élément se termine bientôt » sans le nommer, l'écran verrouillé reste privé.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Les rappels passent par le service de rappels de Shedly. Il ne reçoit que les dates de rappel et tes choix on/off, jamais les noms sauf si tu les actives.",
"Off. Nothing is sent until you turn reminders on.": "Désactivé. Rien n'est envoyé tant que tu n'actives pas les rappels.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Heures calmes : rien entre 21 h et 8 h. Au plus un rappel par jour, et environ deux par semaine.",
"Notifications is where you pick which deadlines to hear about, and when.": "Dans Notifications, tu choisis les échéances dont on te parle et quand.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Les éléments datés peuvent te prévenir avant la fin. Active-le dans Toi → Notifications.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Envie d'être prévenu avant la fin ? Règle les rappels dans Toi → Notifications.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Ta liste est pleine. Lâches-en une pour faire de la place, ou importe un relevé bancaire dans Toi → Importer.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Tout ce qui a une date dans les 30 prochains jours arrive ici, avec ce que ça te coûtera.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Cette ligne sous le titre, c'est Shedly qui remarque quelque chose. Un coup de pouce, jamais une règle.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Chaque broyeuse se gagne. Touche la tienne pour changer plaque, voyant, coupe et son.",
"Your device asks for reduced motion, so shredding is instant.": "Ton appareil demande moins d'animations, le broyage est donc instantané.",
"Rare shred. Gold ones turn up now and then.": "Broyage rare. Les dorés apparaissent de temps en temps.",
"Copied. Paste it anywhere.": "Copié. Colle-le où tu veux.",
"Image saved.": "Image enregistrée.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Colle une liste ou ouvre un relevé bancaire CSV. Il est lu sur cet appareil et jamais envoyé.",
"List or CSV to import": "Liste ou CSV à importer",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Un par ligne :\nNetflix 15 €/mois\nSalle de sport 30 €/mois\nPasseport expire dans 3 semaines\n\nou colle des lignes du CSV de ta banque",
