"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never r": "La dictée utilise le service vocal de ton téléphone. Sur la plupart, ta voix est envoyée à Apple ou Google pour être transcrite. Shedly ne r",
