"Shown on your weekly review. Stays on this device.": "Affiché dans ton bilan hebdomadaire. Reste sur cet appareil.",
"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Partage les écrans et boutons utilisés et enregistre l'aspect des écrans, tout texte masqué. Noms, prix, notes et texte saisi ne sont jamais envoyés. Désactive-le quand tu veux.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Affiche la météo du jour dans le ciel. Demande ta position approximative une fois, puis l'envoie arrondie à environ 10 km à Open-Meteo. Rien d'autre n'est envoyé.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Active les rappels dans Toi, sous Notifications. Choisis les échéances : une semaine, trois jours et un jour avant. <strong>Silence après 21 h, jamais plus d'un par jour.</strong>",
