"Wipe everything?": "Alles löschen?",
"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Das löscht Liste, Verlauf, Maschinen, Serie, Name, Land und Einstellungen von diesem Gerät und startet Shedly wie nach der Installation neu. Das lässt sich nicht rückgängig machen.",
