"Nothing to shed yet.": "Noch nichts zum Loslassen.",
"Nothing shed yet. The first one is the hardest.": "Ancora nulla lasciato. Il primo è il più difficile.",
"Nothing matches.": "Keine Treffer.",
"Add what you've said yes to: tasks, meetings, subscriptions. Tap a few to see how it works.": "Füge hinzu, wozu du Ja gesagt hast: Aufgaben, Termine, Abos. Tippe ein paar an, um es auszuprobieren.",
"+ Gym membership €30/mo": "+ Fitnessstudio 30 €/Monat",
"+ Weekly status meeting": "+ Wöchentliches Statusmeeting",
"+ Streaming plan nobody watches €12/mo": "+ Streaming-Abo, das keiner schaut 12 €/Monat",
"+ Reorganise the garage": "+ Garage aufräumen",
"Skip the tour": "Tour überspringen",
"Start shedding": "Loslassen starten",
"Done": "Fertig",
"A note from Liam.": "Eine Notiz von Liam.",
"Hi, I'm Liam, the founder of Shedly.": "Hi, ich bin Liam, der Gründer von Shedly.",
"Most to-do apps help you add things. Shedly helps you let go of them. Once a week it asks one question about one thing: is this still a yes?": "Die meisten To-do-Apps helfen dir, Dinge hinzuzufügen. Shedly hilft dir, sie loszulassen. Einmal pro Woche stellt sie eine Frage zu einer Sache: Ist das noch ein Ja?",
"Shed it and it goes through the shredder. Keep it and say why. That's the whole app.": "Lass es los und es geht durch den Schredder. Behalte es und sag warum. Das ist die ganze App.",
"No account, no email. Your list stays on this phone.": "Kein Konto, keine E-Mail. Deine Liste bleibt auf diesem Handy.",
"Shedly is new, and I'd love your support and help to make it amazing. Tell me what works and what doesn't.": "Shedly ist neu, und ich freue mich über deine Unterstützung und Hilfe, es großartig zu machen. Sag mir, was funktioniert und was nicht.",
"Founder, Shedly": "Gründer von Shedly",
"Who's shedding?": "Wer lässt los?",
"So names and prices come out right. <strong>No account, no email.</strong>": "Damit Namen und Preise stimmen. <strong>Kein Konto, keine E-Mail.</strong>",
"You can still type $15 or £12 on any item. Prices in different currencies stay separate.": "Du kannst bei jedem Eintrag weiterhin $15 oder £12 eingeben. Preise in verschiedenen Währungen bleiben getrennt.",
"What should we call you?": "Wie sollen wir dich nennen?",
"Pick your look.": "Wähle deinen Look.",
"Dark or light, calm or loud. <strong>Tap one and the app changes right now.</strong>": "Dunkel oder hell, ruhig oder laut. <strong>Tippe auf einen und die App ändert sich sofort.</strong>",
"Weather in your sky.": "Wetter an deinem Himmel.",
"Rain, sun, snow and a real moon, matching what's outside. <strong>Totally optional.</strong>": "Regen, Sonne, Schnee und ein echter Mond, passend zu draußen. <strong>Völlig optional.</strong>",
"Show today's weather in the sky": "Heutiges Wetter im Himmel zeigen",
"Show today's weather": "Heutiges Wetter zeigen",
"Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Fragt einmal nach deinem ungefähren Standort und sendet ihn auf etwa 10 km gerundet an Open-Meteo, um das Wetter abzufragen. Sonst wird nichts gesendet.",
"Hear about it before it ends.": "Erfahre es, bevor es endet.",
"A quiet nudge a week, three days and a day before something ends. <strong>Quiet after 9 pm, never more than one a day.</strong>": "Ein leiser Hinweis eine Woche, drei Tage und einen Tag vor dem Ende. <strong>Ruhe nach 21 Uhr, nie mehr als einer pro Tag.</strong>",
"Remind me before things end": "Vor Ablauf erinnern",
"Your phone will ask for permission. You choose which items remind you, in You → Notifications.": "Dein Handy fragt nach der Erlaubnis. Welche Einträge erinnern, wählst du unter Du → Mitteilungen.",
"Tap, or just swipe.": "Tippen oder einfach wischen.",
"Flick left or right to go from Review to List, Shed and You. <strong>The tabs at the bottom still work either way.</strong>": "Wische nach links oder rechts, um von Prüfen zu Liste, Loslassen und Du zu wechseln. <strong>Die Tabs unten funktionieren weiterhin.</strong>",
"Swipe between screens": "Zwischen Bildschirmen wischen",
"Turn it off any time in You.": "Jederzeit unter Du ausschaltbar.",
"Without": "Ohne",
"With swiping": "Mit Wischen",
"Your list stays on this phone. No account, no email. <strong>Help us test Shedly if you like.</strong>": "Deine Liste bleibt auf diesem Handy. Kein Konto, keine E-Mail. <strong>Hilf uns gern beim Testen von Shedly.</strong>",
"Share anonymous usage": "Anonyme Nutzung teilen",
"Share anonymous usage (testing)": "Anonyme Nutzung teilen (Test)",
"Records which screens and buttons you use, with all text hidden. Item names, prices and notes are never sent. Export or erase everything any time in You.": "Erfasst, welche Bildschirme und Tasten du nutzt, mit komplett verborgenem Text. Namen, Preise und Notizen werden nie gesendet. Exportiere oder lösche alles jederzeit unter Du.",
"Four screens. One swipe.": "Vier Bildschirme. Ein Wisch.",
"Review is your weekly question, List is everything you've said yes to, Shed is your total and your machines, You is settings. <strong>Switch on swiping in You and flick between them.</strong>": "Prüfen ist deine Wochenfrage, Liste alles, wozu du Ja gesagt hast, Loslassen deine Summe und Maschinen, Du die Einstellungen. <strong>Aktiviere Wischen unter Du und wische dazwischen.</strong>",
"A to-do list that gets shorter.": "Eine To-do-Liste, die kürzer wird.",
"Every other app helps you add things. Shedly helps you let go of one. <strong>Once a week.</strong> That's the whole trick.": "Jede andere App hilft dir, Dinge hinzuzufügen. Shedly hilft dir, eines loszulassen. <strong>Einmal pro Woche.</strong> Das ist der ganze Trick.",
"Once a week, one question.": "Einmal pro Woche eine Frage.",
"Add anything you've said yes to: tasks, meetings, subscriptions. Put a price on it and Shedly does the sums. <strong>Yes, even that one you forgot about.</strong>": "Füge alles hinzu, wozu du Ja gesagt hast: Aufgaben, Termine, Abos. Gib einen Preis an und Shedly rechnet. <strong>Ja, auch das, was du vergessen hattest.</strong>",
"It notices things.": "Es bemerkt Dinge.",
"Renewals coming up, what each use really costs, and a line when you've kept something again and again. <strong>Never a rule. Always your call.</strong>": "Anstehende Verlängerungen, was jede Nutzung wirklich kostet, und eine Zeile, wenn du etwas immer wieder behältst. <strong>Nie eine Regel. Immer deine Entscheidung.</strong>",
"Is this still a yes? Shed it, or keep it with one line on why. We'll quote you next time. <strong>“Just in case” is allowed.</strong> It reads worse the second time.": "Ist das noch ein Ja? Lass es los oder behalte es mit einer Zeile, warum. Beim nächsten Mal zitieren wir dich. <strong>„Für alle Fälle“ ist erlaubt.</strong> Beim zweiten Mal klingt es schlechter.",
"Watch the number go up.": "Sieh die Zahl steigen.",
"Every shed adds to your total, and to what you've freed up if it had a price. Miss a week and nothing explodes. <strong>Miss a month and we'll mention it.</strong>": "Jedes Loslassen erhöht deine Summe und das, was du freigesetzt hast, falls es einen Preis hatte. Eine Woche verpasst, nichts explodiert. <strong>Einen Monat verpasst, erwähnen wir es.</strong>",
"Shedding unlocks new machines: at 3, 10, 25 things, and then streaks. Then make it yours with a nameplate, a light and a cut style. <strong>Brass is for the long haul.</strong>": "Loslassen schaltet neue Maschinen frei: bei 3, 10, 25 Dingen und dann durch Serien. Dann mach sie mit Namensschild, Licht und Schnittart zu deiner. <strong>Brass ist für die lange Strecke.</strong>",
"Earn your shredder.": "Verdiene deinen Schredder.",
"Where everyone starts.": "Hier fängt jeder an.",
"Opens full screen from your home screen, works offline, and <strong>is the only way to get reminders on an iPhone.</strong>": "Öffnet im Vollbild vom Home-Bildschirm, funktioniert offline und <strong>ist der einzige Weg zu Erinnerungen auf dem iPhone.</strong>",
"Shedly works best installed.": "Shedly funktioniert installiert am besten.",
