"Erase your list, history and profile from this device? This can't be undone.": "Liste, Verlauf und Profil von diesem Gerät löschen? Das lässt sich nicht rückgängig machen.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Deine Liste liegt auf diesem Gerät, plus Erinnerungsdaten, wenn Erinnerungen an sind. Exportieren gibt dir eine Kopie; Löschen entfernt sie von hier.",
"Help test Shedly": "Hilf beim Testen von Shedly",
"Testing notes": "Testhinweise",
"Read the testing notes": "Testhinweise lesen",
"What we see": "Was wir sehen",
"What we never see": "Was wir nie sehen",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Welche Bildschirme und Tasten du nutzt, deine Serie in Bereichen und Aufzeichnungen mit verborgenem Text.",
"Item names, prices, dates, notes, your name or anything you type.": "Namen, Preise, Daten, Notizen, dein Name oder irgendetwas, das du tippst.",
"Thank you. You're helping us make it better.": "Danke. Du hilfst uns, es besser zu machen.",
"Count me in": "Ich bin dabei",
"Maybe later": "Vielleicht später",
"Not for me": "Nichts für mich",
"You can change this any time in You.": "Das kannst du jederzeit unter Du ändern.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens": "Du gehörst zu den Ersten, die Shedly ausprobieren. <strong>Anonyme Nutzung zu teilen ist der schnellste Weg, es besser zu machen.</strong> Wir sehen, welche Bildschirme",
"Looking back": "Rückblick",
"Don't ask about this one": "Bei diesem nicht mehr fragen",
"Not at all": "Überhaupt nicht",
"A bit": "Ein bisschen",
"Yes, bring it back": "Ja, zurückholen",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "Mitteilungen sind blockiert. Erlaube sie für Shedly in den Handy-Einstellungen.",
"Couldn't turn reminders on. Try again.": "Erinnerungen konnten nicht aktiviert werden. Versuch es erneut.",
"Reminders are on.": "Erinnerungen sind an.",
"Reminders are off.": "Erinnerungen sind aus.",
"Turn reminders on": "Erinnerungen aktivieren",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Füge Shedly auf dem iPhone zum Home-Bildschirm hinzu und öffne es von dort.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Dieser Browser kann keine Erinnerungen senden. Probiere Chrome auf Android oder Safari auf dem iPhone.",
"Item reminders": "Erinnerungen pro Eintrag",
"Deadline reminders": "Fristerinnerungen",
"For items with a date: a week, three days and one day before.": "Für Einträge mit Datum: eine Woche, drei Tage und einen Tag vorher.",
"Sunday evening, when this week's shed is due.": "Sonntagabend, wenn das Loslassen dieser Woche ansteht.",
"At most once a month, for items untouched for 30 days or more.": "Höchstens einmal im Monat, für Einträge, die 30 Tage oder länger unberührt sind.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "Sonntagnachmittag, nur ab einer Serie von zwei Wochen oder mehr.",
"Show item names": "Namen anzeigen",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Aus: Die Erinnerung sagt „Ein Eintrag endet bald“, ohne ihn zu nennen, damit der Sperrbildschirm privat bleibt.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Erinnerungen laufen über Shedlys Erinnerungsdienst. Er erhält nur Erinnerungsdaten und deine An/Aus-Wahl, nie Namen, außer du aktivierst Namen.",
"Off. Nothing is sent until you turn reminders on.": "Aus. Es wird nichts gesendet, bis du Erinnerungen aktivierst.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Ruhezeiten: nichts zwischen 21 und 8 Uhr. Höchstens eine Erinnerung pro Tag und etwa zwei pro Woche.",
"Notifications is where you pick which deadlines to hear about, and when.": "Unter Mitteilungen wählst du, über welche Fristen du informiert wirst und wann.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Einträge mit Datum können dich vor dem Ende erinnern. Aktiviere das unter Du → Mitteilungen.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Möchtest du vor dem Ende Bescheid bekommen? Stelle Erinnerungen unter Du → Mitteilungen ein.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Deine Liste ist voll. Lass einen Eintrag los, um Platz zu schaffen, oder importiere einen Kontoauszug unter Du → Importieren.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Alles mit Datum in den nächsten 30 Tagen landet hier, samt den Kosten.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Die Zeile unter dem Titel ist Shedly, das etwas bemerkt. Ein Anstoß, nie eine Regel.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Jeder Schredder wird verdient. Tippe auf deinen, um Namensschild, Licht, Schnitt und Ton zu ändern.",
"Your device asks for reduced motion, so shredding is instant.": "Dein Gerät verlangt reduzierte Bewegung, daher geht das Schreddern sofort.",
"Rare shred. Gold ones turn up now and then.": "Seltenes Schreddern. Goldene tauchen ab und zu auf.",
"Copied. Paste it anywhere.": "Kopiert. Füge es überall ein.",
"Image saved.": "Bild gespeichert.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Füge eine Liste ein oder öffne einen Kontoauszug als CSV. Er wird auf diesem Gerät gelesen und nie hochgeladen.",
"List or CSV to import": "Liste oder CSV zum Importieren",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Eins pro Zeile:\nNetflix 15 €/Monat\nFitnessstudio 30 €/Monat\nReisepass läuft in 3 Wochen ab\n\noder füge Zeilen aus der CSV deiner Bank ein",
"Or open a file: ": "Oder öffne eine Datei: ",
