"Continue": "Weiter",
"Find things to review": "Dinge zum Prüfen finden",
"Dictate an item": "Eintrag diktieren",
"Dictation": "Diktat",
"Got it, start listening": "Verstanden, Zuhören starten",
"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "Das Mikrofon ist für Shedly aus. Aktiviere es in den Handy- oder Browser-Einstellungen.",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never r": "Diktieren nutzt den Sprachdienst deines Handys. Bei den meisten wird deine Stimme zur Umwandlung in Text an Apple oder Google gesendet. Shedly sp",
"Type it like you'd say it.": "Schreib es so, wie du es sagen würdest.",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "Schreib es natürlich: „Netflix 15 €/Monat“, „Amazon endet Mitte nächsten Monats“, „Reisepass läuft in 3 Wochen ab“.",
