"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Teilt, welche Bildschirme und Tasten du nutzt, und zeichnet auf, wie Bildschirme aussehen, mit verborgenem Text. Namen, Preise, Notizen und getippter Text werden nie gesendet. Jederzeit abschaltbar.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Zeigt das heutige Wetter im Himmel. Fragt einmal nach deinem ungefähren Standort und sendet ihn auf etwa 10 km gerundet an Open-Meteo. Sonst wird nichts gesendet.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Aktiviere Erinnerungen unter Du, bei Mitteilungen. Wähle die Fristen: eine Woche, drei Tage und einen Tag vorher. <strong>Ruhe nach 21 Uhr, nie mehr als eine pro Tag.</strong>",
