"Clean lines, clinical stare. Judges your spelling, quietly.": "Klare Linien, klinischer Blick. Beurteilt still deine Rechtschreibung.",
"Lives for Monday piles. Gets loud about it.": "Lebt für die Montagsstapel. Wird laut deswegen.",
"Built to last. Has never met a subscription it liked.": "Für die Ewigkeit gebaut. Hat noch nie ein Abo gemocht.",
"Only comes out for a proper plan.": "Kommt nur für einen richtigen Plan heraus.",
"Knows exactly what you're avoiding.": "Weiß genau, was du vermeidest.",
"Runs warm and hates being rushed.": "Läuft warm und hasst Hetze.",
"Weathered, patient, a little smug about it.": "Verwittert, geduldig und etwas selbstgefällig.",
"Polished steel. You earned the shine.": "Polierter Stahl. Den Glanz hast du dir verdient.",
"The one you started with. Never once complained.": "Der, mit dem alles begann. Hat sich nie beschwert.",
