"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Questo elimina elenco, cronologia, macchine, serie, nome, paese e impostazioni da questo dispositivo e riavvia Shedly come appena installata. Non si può annullare.",
