"Erase your list, history and profile from this device? This can't be undone.": "Cancellare elenco, cronologia e profilo da questo dispositivo? Non si può annullare.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Il tuo elenco è salvato su questo dispositivo, più le date dei promemoria se attivi. Esporta ti dà una copia; cancella la rimuove da qui.",
