"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Quali schermate e pulsanti usi, la tua serie per fasce e registrazioni con tutto il testo nascosto.",
"Item names, prices, dates, notes, your name or anything you type.": "Nomi, prezzi, date, note, il tuo nome o qualsiasi cosa tu scriva.",
"Thank you. You're helping us make it better.": "Grazie. Ci stai aiutando a migliorarla.",
"Count me in": "Ci sto",
"Maybe later": "Forse più tardi",
"Not for me": "Non fa per me",
"You can change this any time in You.": "Puoi cambiarlo quando vuoi in Tu.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens": "Sei una delle prime persone a provare Shedly. <strong>Condividere l'uso anonimo è il modo più veloce per migliorarla.</strong> Ci mostra quali schermate",
"Looking back": "Uno sguardo indietro",
"Don't ask about this one": "Non chiedere più per questa",
"Not at all": "Per niente",
"A bit": "Un po'",
"Yes, bring it back": "Sì, rimettila",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "Le notifiche sono bloccate. Consentile per Shedly nelle impostazioni del telefono.",
"Couldn't turn reminders on. Try again.": "Impossibile attivare i promemoria. Riprova.",
"Reminders are on.": "Promemoria attivi.",
"Reminders are off.": "Promemoria disattivati.",
"Turn reminders on": "Attiva i promemoria",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Su iPhone, aggiungi Shedly alla schermata Home e aprila da lì.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Questo browser non può inviare promemoria. Prova Chrome su Android o Safari su iPhone.",
"Item reminders": "Promemoria per voce",
"Deadline reminders": "Promemoria di scadenza",
"For items with a date: a week, three days and one day before.": "Per le voci con data: una settimana, tre giorni e un giorno prima.",
"Sunday evening, when this week's shed is due.": "La domenica sera, quando è ora di lasciare qualcosa.",
"At most once a month, for items untouched for 30 days or more.": "Al massimo una volta al mese, per voci intatte da 30 giorni o più.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "La domenica pomeriggio, solo con una serie di due settimane o più.",
"Show item names": "Mostra i nomi",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Disattivato: il promemoria dice «Una voce sta per scadere» senza nominarla, così la schermata di blocco resta privata.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "I promemoria passano dal servizio promemoria di Shedly. Riceve solo le date dei promemoria e le tue scelte on/off, mai i nomi a meno che tu non li attivi.",
"Off. Nothing is sent until you turn reminders on.": "Disattivato. Non viene inviato nulla finché non attivi i promemoria.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Ore di silenzio: niente tra le 21 e le 8. Al massimo un promemoria al giorno e circa due a settimana.",
"Notifications is where you pick which deadlines to hear about, and when.": "In Notifiche scegli di quali scadenze essere avvisato e quando.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Le voci con data possono avvisarti prima della scadenza. Attivalo in Tu → Notifiche.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Vuoi un avviso prima che finisca? Imposta i promemoria in Tu → Notifiche.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Il tuo elenco è pieno. Lasciane una per fare spazio, o importa un estratto conto in Tu → Importa.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Tutto ciò con una data nei prossimi 30 giorni finisce qui, con quanto ti costerà.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Quella riga sotto il titolo è Shedly che nota qualcosa. È uno stimolo, mai una regola.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Ogni distruggidocumenti si guadagna. Tocca il tuo per cambiare targhetta, luce, taglio e suono.",
"Your device asks for reduced motion, so shredding is instant.": "Il tuo dispositivo chiede meno movimento, quindi la triturazione è istantanea.",
"Rare shred. Gold ones turn up now and then.": "Triturazione rara. Quelle dorate compaiono ogni tanto.",
"Copied. Paste it anywhere.": "Copiato. Incollalo ovunque.",
"Image saved.": "Immagine salvata.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Incolla un elenco o apri un estratto conto CSV. Viene letto su questo dispositivo e mai caricato.",
"List or CSV to import": "Elenco o CSV da importare",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Uno per riga:\nNetflix 15 €/mese\nPalestra 30 €/mese\nIl passaporto scade tra 3 settimane\n\no incolla righe dal CSV della tua banca",
