"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "Il microfono è disattivato per Shedly. Attivalo nelle impostazioni del telefono o del browser.",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never r": "La dettatura usa il servizio vocale del tuo telefono. Sulla maggior parte, la tua voce viene inviata ad Apple o Google per trasformarla in testo. Shedly non r",
"Type it like you'd say it.": "Scrivilo come lo diresti.",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "Scrivilo in modo naturale: «Netflix 15 €/mese», «Amazon scade a metà del mese prossimo», «Il passaporto scade tra 3 settimane».",
