"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Condivide quali schermate e pulsanti usi e registra come appaiono, con tutto il testo nascosto. Nomi, prezzi, note e testo digitato non vengono mai inviati. Disattivalo quando vuoi.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Mostra il meteo di oggi nel cielo. Chiede la tua posizione approssimativa una volta e la invia arrotondata a circa 10 km a Open-Meteo. Nient'altro viene inviato.",
