"Clean lines, clinical stare. Judges your spelling, quietly.": "Linee pulite, sguardo clinico. Giudica in silenzio la tua ortografia.",
"Lives for Monday piles. Gets loud about it.": "Vive per le pile del lunedì. E si fa sentire.",
"Built to last. Has never met a subscription it liked.": "Costruita per durare. Non ha mai sopportato un abbonamento.",
"Only comes out for a proper plan.": "Esce solo per un piano serio.",
"Knows exactly what you're avoiding.": "Sa esattamente cosa stai evitando.",
"Runs warm and hates being rushed.": "Va caldo e odia la fretta.",
"Weathered, patient, a little smug about it.": "Logorata, paziente e un po' compiaciuta.",
"Polished steel. You earned the shine.": "Acciaio lucidato. Il lustro te lo sei guadagnato.",
"The one you started with. Never once complained.": "Quella con cui hai iniziato. Non si è mai lamentata.",
"Shed 3 things to meet it.": "Elimina 3 cose per conoscerla.",
