"Add what you've said yes to: tasks, meetings, subscriptions. Tap a few to see how it works.": "Adiciona aquilo a que disseste sim: tarefas, reuniões, subscrições. Toca em algumas para ver como funciona.",
"+ Gym membership €30/mo": "+ Mensalidade do ginásio 30 €/mês",
"+ Weekly status meeting": "+ Reunião semanal de ponto de situação",
"+ Streaming plan nobody watches €12/mo": "+ Plano de streaming que ninguém vê 12 €/mês",
"+ Reorganise the garage": "+ Reorganizar a garagem",
"Skip the tour": "Saltar o tutorial",
"Start shedding": "Começar a soltar",
"Done": "Concluído",
"A note from Liam.": "Uma nota do Liam.",
"Hi, I'm Liam, the founder of Shedly.": "Olá, sou o Liam, o fundador do Shedly.",
"Most to-do apps help you add things. Shedly helps you let go of them. Once a week it asks one question about one thing: is this still a yes?": "A maioria das apps de tarefas ajuda-te a adicionar coisas. O Shedly ajuda-te a largá-las. Uma vez por semana faz uma pergunta sobre uma coisa: ainda é um sim?",
"Shed it and it goes through the shredder. Keep it and say why. That's the whole app.": "Solta-o e passa pela trituradora. Mantém-no e diz porquê. É esta a app toda.",
"No account, no email. Your list stays on this phone.": "Sem conta, sem email. A tua lista fica neste telemóvel.",
"Shedly is new, and I'd love your support and help to make it amazing. Tell me what works and what doesn't.": "O Shedly é novo e adorava o teu apoio e ajuda para o tornar incrível. Diz-me o que funciona e o que não funciona.",
"Founder, Shedly": "Fundador do Shedly",
"Who's shedding?": "Quem vai soltar?",
"So names and prices come out right. <strong>No account, no email.</strong>": "Para nomes e preços saírem certos. <strong>Sem conta, sem email.</strong>",
"You can still type $15 or £12 on any item. Prices in different currencies stay separate.": "Podes sempre escrever $15 ou £12 em qualquer item. Os preços em moedas diferentes ficam separados.",
"What should we call you?": "Como te devemos chamar?",
"Pick your look.": "Escolhe o teu aspeto.",
"Dark or light, calm or loud. <strong>Tap one and the app changes right now.</strong>": "Escuro ou claro, calmo ou vibrante. <strong>Toca num e a app muda logo.</strong>",
"Weather in your sky.": "O tempo no teu céu.",
"Rain, sun, snow and a real moon, matching what's outside. <strong>Totally optional.</strong>": "Chuva, sol, neve e uma lua real, como lá fora. <strong>Totalmente opcional.</strong>",
"Show today's weather in the sky": "Mostrar o tempo de hoje no céu",
"Show today's weather": "Mostrar o tempo de hoje",
"Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Pede a tua localização aproximada uma vez e envia-a arredondada a cerca de 10 km para o Open-Meteo consultar o tempo. Mais nada é enviado.",
"Hear about it before it ends.": "Sabe antes de terminar.",
"A quiet nudge a week, three days and a day before something ends. <strong>Quiet after 9 pm, never more than one a day.</strong>": "Um aviso discreto uma semana, três dias e um dia antes de algo terminar. <strong>Silêncio depois das 21h, nunca mais de um por dia.</strong>",
"Remind me before things end": "Avisar-me antes de terminar",
"Your phone will ask for permission. You choose which items remind you, in You → Notifications.": "O teu telemóvel vai pedir permissão. Escolhes que itens te avisam em Tu → Notificações.",
"Tap, or just swipe.": "Toca, ou simplesmente desliza.",
"Flick left or right to go from Review to List, Shed and You. <strong>The tabs at the bottom still work either way.</strong>": "Desliza para a esquerda ou direita para ir de Rever a Lista, Soltar e Tu. <strong>Os separadores em baixo continuam a funcionar.</strong>",
"Swipe between screens": "Deslizar entre ecrãs",
"Turn it off any time in You.": "Desativa quando quiseres em Tu.",
"Without": "Sem",
"With swiping": "Com deslize",
"Your list stays on this phone. No account, no email. <strong>Help us test Shedly if you like.</strong>": "A tua lista fica neste telemóvel. Sem conta, sem email. <strong>Ajuda-nos a testar o Shedly, se quiseres.</strong>",
"Share anonymous usage": "Partilhar utilização anónima",
"Share anonymous usage (testing)": "Partilhar utilização anónima (teste)",
"Records which screens and buttons you use, with all text hidden. Item names, prices and notes are never sent. Export or erase everything any time in You.": "Regista que ecrãs e botões usas, com todo o texto oculto. Nomes, preços e notas nunca são enviados. Exporta ou apaga tudo quando quiseres em Tu.",
"Four screens. One swipe.": "Quatro ecrãs. Um deslize.",
"Review is your weekly question, List is everything you've said yes to, Shed is your total and your machines, You is settings. <strong>Switch on swiping in You and flick between them.</strong>": "Rever é a tua pergunta semanal, Lista é tudo a que disseste sim, Soltar é o teu total e as tuas máquinas, Tu são as definições. <strong>Ativa o deslize em Tu e passa de um para o outro.</strong>",
"A to-do list that gets shorter.": "Uma lista de tarefas que encurta.",
"Every other app helps you add things. Shedly helps you let go of one. <strong>Once a week.</strong> That's the whole trick.": "Todas as outras apps ajudam-te a adicionar coisas. O Shedly ajuda-te a largar uma. <strong>Uma vez por semana.</strong> É esse o truque todo.",
"Once a week, one question.": "Uma vez por semana, uma pergunta.",
"Add anything you've said yes to: tasks, meetings, subscriptions. Put a price on it and Shedly does the sums. <strong>Yes, even that one you forgot about.</strong>": "Adiciona tudo a que disseste sim: tarefas, reuniões, subscrições. Põe um preço e o Shedly faz as contas. <strong>Sim, até aquela de que te esqueceste.</strong>",
"It notices things.": "Repara nas coisas.",
"Renewals coming up, what each use really costs, and a line when you've kept something again and again. <strong>Never a rule. Always your call.</strong>": "Renovações a chegar, quanto custa realmente cada uso e uma linha quando manténs algo uma e outra vez. <strong>Nunca uma regra. Sempre decisão tua.</strong>",
"Is this still a yes? Shed it, or keep it with one line on why. We'll quote you next time. <strong>“Just in case” is allowed.</strong> It reads worse the second time.": "Ainda é um sim? Solta-o ou mantém com uma linha a explicar porquê. Da próxima vez citamos-te. <strong>“Por precaução” é permitido.</strong> Lê-se pior à segunda vez.",
"Watch the number go up.": "Vê o número a subir.",
"Every shed adds to your total, and to what you've freed up if it had a price. Miss a week and nothing explodes. <strong>Miss a month and we'll mention it.</strong>": "Cada coisa solta soma ao teu total e ao que libertaste, se tinha preço. Falha uma semana e nada explode. <strong>Falha um mês e comentamos.</strong>",
"Shedding unlocks new machines: at 3, 10, 25 things, and then streaks. Then make it yours with a nameplate, a light and a cut style. <strong>Brass is for the long haul.</strong>": "Soltar desbloqueia novas máquinas: às 3, 10, 25 coisas e depois com sequências. Depois personaliza com uma placa, uma luz e um estilo de corte. <strong>Brass é para quem vai longe.</strong>",
"Earn your shredder.": "Ganha a tua trituradora.",
"Where everyone starts.": "Onde todos começam.",
"Opens full screen from your home screen, works offline, and <strong>is the only way to get reminders on an iPhone.</strong>": "Abre em ecrã inteiro a partir do ecrã principal, funciona offline e <strong>é a única forma de receber lembretes num iPhone.</strong>",
"Shedly works best installed.": "O Shedly funciona melhor instalado.",
