"Erase everything": "Apagar tudo",
"Erase your list, history and profile from this device? This can't be undone.": "Apagar a tua lista, histórico e perfil deste dispositivo? Não se pode anular.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "A tua lista fica guardada neste dispositivo, mais as datas dos lembretes se estiverem ativos. Exportar dá-te uma cópia; apagar remove-a daqui.",
"Help test Shedly": "Ajuda a testar o Shedly",
"Testing notes": "Notas de teste",
"Read the testing notes": "Lê as notas de teste",
"What we see": "O que vemos",
"What we never see": "O que nunca vemos",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Que ecrãs e botões usas, a tua sequência em intervalos e gravações com todo o texto oculto.",
"Item names, prices, dates, notes, your name or anything you type.": "Nomes, preços, datas, notas, o teu nome ou qualquer coisa que escrevas.",
"Thank you. You're helping us make it better.": "Obrigado. Estás a ajudar-nos a melhorá-lo.",
"Count me in": "Conta comigo",
"Maybe later": "Talvez mais tarde",
"Not for me": "Não é para mim",
"You can change this any time in You.": "Podes alterar isto quando quiseres em Tu.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens": "És das primeiras pessoas a experimentar o Shedly. <strong>Partilhar utilização anónima é a forma mais rápida de o melhorar.</strong> Mostra-nos que ecrãs",
"Looking back": "A olhar para trás",
"Don't ask about this one": "Não perguntar sobre esta",
"Not at all": "Nada",
"A bit": "Um pouco",
"Yes, bring it back": "Sim, trazer de volta",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "As notificações estão bloqueadas. Permite-as para o Shedly nas definições do telemóvel.",
"Couldn't turn reminders on. Try again.": "Não foi possível ativar os lembretes. Tenta de novo.",
"Reminders are on.": "Lembretes ativados.",
"Reminders are off.": "Lembretes desativados.",
"Turn reminders on": "Ativar lembretes",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "No iPhone, adiciona o Shedly ao ecrã principal e abre-o a partir daí.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Este navegador não pode enviar lembretes. Experimenta o Chrome no Android ou o Safari no iPhone.",
"Item reminders": "Lembretes por item",
"Deadline reminders": "Lembretes de prazos",
"For items with a date: a week, three days and one day before.": "Para itens com data: uma semana, três dias e um dia antes.",
"Sunday evening, when this week's shed is due.": "Ao domingo à noite, quando é hora de soltar algo esta semana.",
"At most once a month, for items untouched for 30 days or more.": "No máximo uma vez por mês, para itens intocados há 30 dias ou mais.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "Ao domingo à tarde, só quando tens uma sequência de duas semanas ou mais.",
"Show item names": "Mostrar nomes",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Desativado: o lembrete diz “Um item termina em breve” sem o nomear, para o ecrã de bloqueio ficar privado.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Os lembretes são enviados pelo serviço de lembretes do Shedly. Só recebe datas de lembretes e as tuas escolhas de ativar/desativar, e nunca nomes, a menos que atives os nomes.",
"Off. Nothing is sent until you turn reminders on.": "Desativado. Nada é enviado até ativares os lembretes.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Horas de silêncio: nada entre as 21h e as 8h. No máximo um lembrete por dia e cerca de dois por semana.",
"Notifications is where you pick which deadlines to hear about, and when.": "Em Notificações escolhes de que prazos queres ser avisado e quando.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Os itens com data podem avisar-te antes de terminar. Ativa isso em Tu → Notificações.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Queres um aviso antes de terminar? Define lembretes em Tu → Notificações.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "A tua lista está cheia. Solta uma para fazer espaço, ou importa um extrato bancário em Tu → Importar.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Tudo o que tenha data nos próximos 30 dias aparece aqui, com o que te vai custar.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Essa linha por baixo do título é o Shedly a reparar em algo. É um empurrão, nunca uma regra.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Cada trituradora é ganha. Toca na tua para mudar placa, luz, corte e som.",
"Your device asks for reduced motion, so shredding is instant.": "O teu dispositivo pede menos movimento, por isso a trituração é instantânea.",
"Rare shred. Gold ones turn up now and then.": "Trituração rara. As douradas aparecem de vez em quando.",
"Copied. Paste it anywhere.": "Copiado. Cola onde quiseres.",
"Image saved.": "Imagem guardada.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Cola uma lista ou abre um CSV de extrato bancário. É lido neste dispositivo e nunca enviado.",
"List or CSV to import": "Lista ou CSV para importar",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Um por linha:\nNetflix 15 €/mês\nGinásio 30 €/mês\nPassaporte expira em 3 semanas\n\nou cola linhas do CSV do teu banco",
"Or open a file: ": "Ou abre um ficheiro: ",
"Choose a file": "Escolher ficheiro",
"Continue": "Continuar",
"Find things to review": "Encontrar coisas para rever",
"Dictate an item": "Ditar um item",
"Dictation": "Ditado",
"Got it, start listening": "Entendi, começa a ouvir",
"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "O microfone está desativado para o Shedly. Ativa-o nas definições do telemóvel ou do navegador.",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never r": "O ditado usa o serviço de voz do teu telemóvel. Na maioria, a tua voz é enviada à Apple ou à Google para ser convertida em texto. O Shedly nunca r",
"Type it like you'd say it.": "Escreve como dirias.",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "Escreve naturalmente: “Netflix 15 €/mês”, “Amazon termina a meio do mês que vem”, “Passaporte expira em 3 semanas”.",
