"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Partilha que ecrãs e botões usas e grava o aspeto dos ecrãs com todo o texto oculto. Nomes, preços, notas e texto escrito nunca são enviados. Desativa quando quiseres.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Mostra o tempo de hoje no céu. Pede a tua localização aproximada uma vez e envia-a arredondada a cerca de 10 km para o Open-Meteo. Mais nada é enviado.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Ativa os lembretes em Tu, em Notificações. Escolhe os prazos: uma semana, três dias e um dia antes. <strong>Silêncio depois das 21h, nunca mais de um por dia.</strong>",
