"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Dit wist je lijst, geschiedenis, machines, reeks, naam, land en instellingen van dit apparaat en start Shedly opnieuw op, alsof je het net hebt geïnstalleerd. Dit kan niet ongedaan worden gemaakt.",
