"Nothing shed yet. The first one is the hardest.": "Nog niets losgelaten. De eerste is het moeilijkst.",
"Nothing matches.": "Geen resultaten.",
"Add what you've said yes to: tasks, meetings, subscriptions. Tap a few to see how it works.": "Voeg toe waar je ja op zei: taken, afspraken, abonnementen. Tik er een paar aan om te zien hoe het werkt.",
"+ Gym membership €30/mo": "+ Sportschool €30/mnd",
"+ Weekly status meeting": "+ Wekelijkse statusvergadering",
"+ Streaming plan nobody watches €12/mo": "+ Streamingabonnement dat niemand kijkt €12/mnd",
"+ Reorganise the garage": "+ De garage opruimen",
"Skip the tour": "Tour overslaan",
"Start shedding": "Begin met loslaten",
"Done": "Klaar",
"A note from Liam.": "Een bericht van Liam.",
"Hi, I'm Liam, the founder of Shedly.": "Hoi, ik ben Liam, de oprichter van Shedly.",
"Most to-do apps help you add things. Shedly helps you let go of them. Once a week it asks one question about one thing: is this still a yes?": "De meeste to-do-apps helpen je dingen toe te voegen. Shedly helpt je ze los te laten. Eén keer per week stelt het één vraag over één ding: is dit nog steeds een ja?",
"Shed it and it goes through the shredder. Keep it and say why. That's the whole app.": "Laat het los en het gaat door de versnipperaar. Houd het en zeg waarom. Dat is de hele app.",
"No account, no email. Your list stays on this phone.": "Geen account, geen e-mail. Je lijst blijft op deze telefoon.",
"Shedly is new, and I'd love your support and help to make it amazing. Tell me what works and what doesn't.": "Shedly is nieuw en ik zou je steun en hulp geweldig vinden om het fantastisch te maken. Vertel me wat werkt en wat niet.",
"Founder, Shedly": "Oprichter van Shedly",
"Who's shedding?": "Wie laat los?",
"So names and prices come out right. <strong>No account, no email.</strong>": "Zodat namen en prijzen kloppen. <strong>Geen account, geen e-mail.</strong>",
"You can still type $15 or £12 on any item. Prices in different currencies stay separate.": "Je kunt bij elk item nog steeds $15 of £12 typen. Prijzen in verschillende valuta blijven gescheiden.",
"What should we call you?": "Hoe mogen we je noemen?",
"Pick your look.": "Kies je uiterlijk.",
"Dark or light, calm or loud. <strong>Tap one and the app changes right now.</strong>": "Donker of licht, rustig of opvallend. <strong>Tik er een aan en de app verandert meteen.</strong>",
"Weather in your sky.": "Weer in je lucht.",
"Rain, sun, snow and a real moon, matching what's outside. <strong>Totally optional.</strong>": "Regen, zon, sneeuw en een echte maan, zoals buiten. <strong>Helemaal optioneel.</strong>",
"Show today's weather in the sky": "Toon het weer van vandaag in de lucht",
"Show today's weather": "Toon het weer van vandaag",
"Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Vraagt één keer om je geschatte locatie en stuurt die afgerond op ongeveer 10 km naar Open-Meteo om het weer op te zoeken. Verder wordt niets verstuurd.",
"Hear about it before it ends.": "Hoor het voordat het afloopt.",
"A quiet nudge a week, three days and a day before something ends. <strong>Quiet after 9 pm, never more than one a day.</strong>": "Een rustige herinnering een week, drie dagen en een dag voordat iets afloopt. <strong>Stil na 21.00 uur, nooit meer dan één per dag.</strong>",
"Remind me before things end": "Herinner me voordat dingen aflopen",
"Your phone will ask for permission. You choose which items remind you, in You → Notifications.": "Je telefoon vraagt om toestemming. Jij kiest welke items je herinneren, bij Jij → Meldingen.",
"Tap, or just swipe.": "Tik, of veeg gewoon.",
"Flick left or right to go from Review to List, Shed and You. <strong>The tabs at the bottom still work either way.</strong>": "Veeg naar links of rechts om van Bekijken naar Lijst, Loslaten en Jij te gaan. <strong>De tabs onderaan werken nog steeds.</strong>",
"Swipe between screens": "Vegen tussen schermen",
"Turn it off any time in You.": "Je kunt het altijd uitzetten bij Jij.",
"Without": "Zonder",
"With swiping": "Met vegen",
"Your list stays on this phone. No account, no email. <strong>Help us test Shedly if you like.</strong>": "Je lijst blijft op deze telefoon. Geen account, geen e-mail. <strong>Help ons Shedly te testen als je wilt.</strong>",
"Share anonymous usage": "Anoniem gebruik delen",
"Share anonymous usage (testing)": "Anoniem gebruik delen (test)",
"Records which screens and buttons you use, with all text hidden. Item names, prices and notes are never sent. Export or erase everything any time in You.": "Registreert welke schermen en knoppen je gebruikt, met alle tekst verborgen. Namen, prijzen en notities worden nooit verstuurd. Exporteer of wis alles op elk moment bij Jij.",
"Four screens. One swipe.": "Vier schermen. Eén veeg.",
"Review is your weekly question, List is everything you've said yes to, Shed is your total and your machines, You is settings. <strong>Switch on swiping in You and flick between them.</strong>": "Bekijken is je wekelijkse vraag, Lijst is alles waar je ja op zei, Loslaten is je totaal en je machines, Jij zijn de instellingen. <strong>Zet vegen aan bij Jij en veeg ertussen.</strong>",
"A to-do list that gets shorter.": "Een to-dolijst die korter wordt.",
"Every other app helps you add things. Shedly helps you let go of one. <strong>Once a week.</strong> That's the whole trick.": "Elke andere app helpt je dingen toe te voegen. Shedly helpt je er één los te laten. <strong>Eén keer per week.</strong> Dat is de hele truc.",
"Once a week, one question.": "Eén keer per week, één vraag.",
"Add anything you've said yes to: tasks, meetings, subscriptions. Put a price on it and Shedly does the sums. <strong>Yes, even that one you forgot about.</strong>": "Voeg alles toe waar je ja op zei: taken, afspraken, abonnementen. Zet er een prijs op en Shedly rekent. <strong>Ja, zelfs die ene die je vergeten was.</strong>",
"It notices things.": "Het merkt dingen op.",
"Renewals coming up, what each use really costs, and a line when you've kept something again and again. <strong>Never a rule. Always your call.</strong>": "Aankomende verlengingen, wat elk gebruik echt kost en een regel als je iets steeds opnieuw houdt. <strong>Nooit een regel. Altijd jouw keuze.</strong>",
"Is this still a yes? Shed it, or keep it with one line on why. We'll quote you next time. <strong>“Just in case” is allowed.</strong> It reads worse the second time.": "Is dit nog steeds een ja? Laat het los, of houd het met één regel waarom. Volgende keer citeren we je. <strong>“Voor het geval dat” mag.</strong> De tweede keer klinkt het slechter.",
"Watch the number go up.": "Zie het getal stijgen.",
"Every shed adds to your total, and to what you've freed up if it had a price. Miss a week and nothing explodes. <strong>Miss a month and we'll mention it.</strong>": "Elk ding dat je loslaat telt mee in je totaal, en in wat je hebt vrijgemaakt als er een prijs aan hing. Mis een week en er explodeert niets. <strong>Mis een maand en we noemen het.</strong>",
"Shedding unlocks new machines: at 3, 10, 25 things, and then streaks. Then make it yours with a nameplate, a light and a cut style. <strong>Brass is for the long haul.</strong>": "Loslaten ontgrendelt nieuwe machines: bij 3, 10, 25 dingen en daarna met reeksen. Maak hem daarna de jouwe met een naamplaatje, een lampje en een snijstijl. <strong>Brass is voor de lange adem.</strong>",
"Earn your shredder.": "Verdien je versnipperaar.",
"Where everyone starts.": "Waar iedereen begint.",
"Opens full screen from your home screen, works offline, and <strong>is the only way to get reminders on an iPhone.</strong>": "Opent op volledig scherm vanaf je beginscherm, werkt offline en <strong>is de enige manier om herinneringen op een iPhone te krijgen.</strong>",
"Shedly works best installed.": "Shedly werkt het best geïnstalleerd.",
"Install Shedly": "Shedly installeren",
"Not installed yet": "Nog niet geïnstalleerd",
