"Erase your list, history and profile from this device? This can't be undone.": "Je lijst, geschiedenis en profiel van dit apparaat wissen? Dit kan niet ongedaan worden gemaakt.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Je lijst staat op dit apparaat, plus herinneringsdata als herinneringen aan staan. Exporteren geeft je een kopie; wissen verwijdert hem hier.",
