"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Welke schermen en knoppen je gebruikt, je reeks in bereiken en opnames met alle tekst verborgen.",
"Item names, prices, dates, notes, your name or anything you type.": "Namen, prijzen, data, notities, je naam of iets wat je typt.",
