"You can change this any time in You.": "Je kunt dit altijd wijzigen bij Jij.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens": "Je bent een van de eersten die Shedly uitprobeert. <strong>Anoniem gebruik delen is de snelste manier om het beter te maken.</strong> Het laat ons zien welke schermen",
