"Notifications are blocked. Allow them for Shedly in your phone settings.": "Meldingen zijn geblokkeerd. Sta ze toe voor Shedly in de instellingen van je telefoon.",
"Couldn't turn reminders on. Try again.": "Herinneringen konden niet worden aangezet. Probeer het opnieuw.",
"Reminders are on.": "Herinneringen staan aan.",
"Reminders are off.": "Herinneringen staan uit.",
"Turn reminders on": "Herinneringen aanzetten",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Voeg Shedly op iPhone toe aan je beginscherm en open het van daaruit.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Deze browser kan geen herinneringen sturen. Probeer Chrome op Android of Safari op iPhone.",
"Item reminders": "Herinneringen per item",
"Deadline reminders": "Herinneringen voor deadlines",
"For items with a date: a week, three days and one day before.": "Voor items met een datum: een week, drie dagen en een dag van tevoren.",
"Sunday evening, when this week's shed is due.": "Zondagavond, wanneer het loslaten van deze week aan de beurt is.",
"At most once a month, for items untouched for 30 days or more.": "Hooguit één keer per maand, voor items die 30 dagen of langer onaangeroerd zijn.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "Zondagmiddag, alleen als je een reeks van twee weken of meer hebt.",
"Show item names": "Namen tonen",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Uit: een herinnering zegt “Een item loopt binnenkort af” zonder het te noemen, zodat je vergrendelscherm privé blijft.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Herinneringen lopen via de herinneringsdienst van Shedly. Die krijgt alleen herinneringsdata en je aan/uit-keuzes, en nooit namen tenzij je namen aanzet.",
"Off. Nothing is sent until you turn reminders on.": "Uit. Er wordt niets verstuurd tot je herinneringen aanzet.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Stille uren: niets tussen 21.00 en 8.00 uur. Hooguit één herinnering per dag en ongeveer twee per week.",
"Notifications is where you pick which deadlines to hear about, and when.": "Bij Meldingen kies je over welke deadlines je hoort, en wanneer.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Items met een datum kunnen je waarschuwen voordat ze aflopen. Zet dat aan bij Jij → Meldingen.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Wil je een seintje voordat dit afloopt? Stel herinneringen in bij Jij → Meldingen.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Je lijst is vol. Laat er een los om ruimte te maken, of importeer een bankafschrift via Jij → Importeren.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Alles met een datum in de komende 30 dagen komt hier terecht, met wat het je kost.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Die regel onder de titel is Shedly die iets opmerkt. Een duwtje, nooit een regel.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Elke versnipperaar verdien je. Tik op die van jou om naamplaatje, lampje, snit en geluid te wijzigen.",
"Your device asks for reduced motion, so shredding is instant.": "Je apparaat vraagt om minder beweging, dus het versnipperen gaat direct.",
"Rare shred. Gold ones turn up now and then.": "Zeldzaam versnipperen. Gouden komen nu en dan voorbij.",
"Copied. Paste it anywhere.": "Gekopieerd. Plak het waar je wilt.",
"Image saved.": "Afbeelding opgeslagen.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Plak een lijst of open een CSV-bankafschrift. Het wordt op dit apparaat gelezen en nooit geüpload.",
"List or CSV to import": "Lijst of CSV om te importeren",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Eén per regel:\nNetflix €15/mnd\nSportschool €30/mnd\nPaspoort verloopt over 3 weken\n\nof plak rijen uit de CSV van je bank",
