"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never r": "Dicteren gebruikt de spraakdienst van je telefoon. Op de meeste telefoons wordt je stem naar Apple of Google gestuurd om tekst te maken. Shedly neemt nooit",
