"Shown on your weekly review. Stays on this device.": "Getoond in je wekelijkse review. Blijft op dit apparaat.",
"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Deelt welke schermen en knoppen je gebruikt en neemt op hoe schermen eruitzien met alle tekst verborgen. Namen, prijzen, notities en getypte tekst worden nooit verstuurd. Je kunt het altijd uitzetten.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Toont het weer van vandaag in de lucht. Vraagt één keer om je geschatte locatie en stuurt die afgerond op ongeveer 10 km naar Open-Meteo. Verder wordt niets verstuurd.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Zet herinneringen aan bij Jij, onder Meldingen. Kies de deadlines: een week, drie dagen en een dag van tevoren. <strong>Stil na 21.00 uur en nooit meer dan één per dag.</strong>",
