"Clean lines, clinical stare. Judges your spelling, quietly.": "Strakke lijnen, klinische blik. Beoordeelt stilletjes je spelling.",
"Lives for Monday piles. Gets loud about it.": "Leeft voor de maandagstapels. Wordt er luid over.",
"Built to last. Has never met a subscription it liked.": "Gebouwd om lang mee te gaan. Heeft nog nooit een abonnement gemogen.",
"Only comes out for a proper plan.": "Komt alleen uit voor een goed plan.",
"Knows exactly what you're avoiding.": "Weet precies wat je vermijdt.",
"Runs warm and hates being rushed.": "Loopt warm en haat haast.",
"Weathered, patient, a little smug about it.": "Verweerd, geduldig en een beetje zelfingenomen.",
"Polished steel. You earned the shine.": "Gepolijst staal. De glans heb je verdiend.",
"The one you started with. Never once complained.": "Degene waarmee je begon. Nooit geklaagd.",
