"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "To usunie z tego urządzenia Twoją listę, historię, maszyny, serię, imię, kraj i ustawienia, a następnie uruchomi Shedly od nowa, jakbyś dopiero go zainstalował. Nie można tego cofnąć.",
