"Add what you've said yes to: tasks, meetings, subscriptions. Tap a few to see how it works.": "Dodaj to, na co się zgodziłeś: zadania, spotkania, subskrypcje. Dotknij kilku, by zobaczyć, jak to działa.",
"+ Gym membership €30/mo": "+ Karnet na siłownię 30 €/mies.",
"+ Weekly status meeting": "+ Cotygodniowe spotkanie statusowe",
"+ Streaming plan nobody watches €12/mo": "+ Plan streamingowy, którego nikt nie ogląda 12 €/mies.",
"+ Reorganise the garage": "+ Uporządkuj garaż",
"Skip the tour": "Pomiń wprowadzenie",
"Start shedding": "Zacznij puszczać",
"Done": "Gotowe",
"A note from Liam.": "Wiadomość od Liama.",
"Hi, I'm Liam, the founder of Shedly.": "Cześć, jestem Liam, założyciel Shedly.",
"Most to-do apps help you add things. Shedly helps you let go of them. Once a week it asks one question about one thing: is this still a yes?": "Większość aplikacji do zadań pomaga dodawać rzeczy. Shedly pomaga je puszczać. Raz w tygodniu zadaje jedno pytanie o jedną rzecz: czy to nadal tak?",
"Shed it and it goes through the shredder. Keep it and say why. That's the whole app.": "Puść to i przejdzie przez niszczarkę. Zachowaj i powiedz dlaczego. To cała aplikacja.",
"No account, no email. Your list stays on this phone.": "Bez konta, bez e-maila. Twoja lista zostaje na tym telefonie.",
"Shedly is new, and I'd love your support and help to make it amazing. Tell me what works and what doesn't.": "Shedly jest nowe i bardzo liczę na Twoje wsparcie i pomoc, by było świetne. Powiedz mi, co działa, a co nie.",
"Founder, Shedly": "Założyciel Shedly",
"Who's shedding?": "Kto puszcza?",
"So names and prices come out right. <strong>No account, no email.</strong>": "Żeby imiona i ceny wyświetlały się poprawnie. <strong>Bez konta, bez e-maila.</strong>",
"You can still type $15 or £12 on any item. Prices in different currencies stay separate.": "Nadal możesz wpisać $15 lub £12 przy dowolnej pozycji. Ceny w różnych walutach pozostają osobno.",
"What should we call you?": "Jak mamy się do Ciebie zwracać?",
"Pick your look.": "Wybierz wygląd.",
"Dark or light, calm or loud. <strong>Tap one and the app changes right now.</strong>": "Ciemny lub jasny, spokojny lub wyrazisty. <strong>Dotknij jednego, a aplikacja zmieni się od razu.</strong>",
"Weather in your sky.": "Pogoda na Twoim niebie.",
"Rain, sun, snow and a real moon, matching what's outside. <strong>Totally optional.</strong>": "Deszcz, słońce, śnieg i prawdziwy księżyc, jak za oknem. <strong>Całkowicie opcjonalne.</strong>",
"Show today's weather in the sky": "Pokaż dzisiejszą pogodę na niebie",
"Show today's weather": "Pokaż dzisiejszą pogodę",
"Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Raz prosi o Twoją przybliżoną lokalizację, po czym wysyła ją zaokrągloną do ok. 10 km do Open-Meteo, aby sprawdzić pogodę. Nic więcej nie jest wysyłane.",
"Hear about it before it ends.": "Dowiedz się, zanim się skończy.",
"A quiet nudge a week, three days and a day before something ends. <strong>Quiet after 9 pm, never more than one a day.</strong>": "Dyskretne przypomnienie tydzień, trzy dni i dzień przed końcem. <strong>Cisza po 21:00, nigdy więcej niż jedno dziennie.</strong>",
"Remind me before things end": "Przypominaj przed końcem",
"Your phone will ask for permission. You choose which items remind you, in You → Notifications.": "Telefon poprosi o zgodę. To Ty wybierasz, które pozycje przypominają, w Ty → Powiadomienia.",
"Tap, or just swipe.": "Dotknij albo po prostu przesuń.",
"Flick left or right to go from Review to List, Shed and You. <strong>The tabs at the bottom still work either way.</strong>": "Przesuń w lewo lub w prawo, by przejść od Przeglądu do Listy, Puść i Ty. <strong>Zakładki na dole nadal działają.</strong>",
"Swipe between screens": "Przesuwaj między ekranami",
"Turn it off any time in You.": "Możesz to wyłączyć w dowolnym momencie w Ty.",
"Without": "Bez",
"With swiping": "Z przesuwaniem",
"Your list stays on this phone. No account, no email. <strong>Help us test Shedly if you like.</strong>": "Twoja lista zostaje na tym telefonie. Bez konta, bez e-maila. <strong>Pomóż nam testować Shedly, jeśli chcesz.</strong>",
"Share anonymous usage": "Udostępniaj anonimowe dane o użyciu",
"Share anonymous usage (testing)": "Udostępniaj anonimowe dane o użyciu (testy)",
"Records which screens and buttons you use, with all text hidden. Item names, prices and notes are never sent. Export or erase everything any time in You.": "Zapisuje, z jakich ekranów i przycisków korzystasz, z ukrytym tekstem. Nazwy, ceny i notatki nigdy nie są wysyłane. Eksportuj lub usuń wszystko w dowolnym momencie w Ty.",
"Four screens. One swipe.": "Cztery ekrany. Jedno przesunięcie.",
"Review is your weekly question, List is everything you've said yes to, Shed is your total and your machines, You is settings. <strong>Switch on swiping in You and flick between them.</strong>": "Przegląd to Twoje cotygodniowe pytanie, Lista to wszystko, na co się zgodziłeś, Puść to Twój wynik i maszyny, Ty to ustawienia. <strong>Włącz przesuwanie w Ty i przełączaj się między nimi.</strong>",
"A to-do list that gets shorter.": "Lista zadań, która się skraca.",
"Every other app helps you add things. Shedly helps you let go of one. <strong>Once a week.</strong> That's the whole trick.": "Każda inna aplikacja pomaga dodawać rzeczy. Shedly pomaga puścić jedną. <strong>Raz w tygodniu.</strong> To cała sztuczka.",
"Once a week, one question.": "Raz w tygodniu, jedno pytanie.",
"Add anything you've said yes to: tasks, meetings, subscriptions. Put a price on it and Shedly does the sums. <strong>Yes, even that one you forgot about.</strong>": "Dodaj wszystko, na co się zgodziłeś: zadania, spotkania, subskrypcje. Wpisz cenę, a Shedly policzy. <strong>Tak, nawet tę, o której zapomniałeś.</strong>",
"It notices things.": "Dostrzega rzeczy.",
"Renewals coming up, what each use really costs, and a line when you've kept something again and again. <strong>Never a rule. Always your call.</strong>": "Zbliżające się odnowienia, ile naprawdę kosztuje każde użycie i uwaga, gdy zachowujesz coś raz po raz. <strong>Nigdy zasada. Zawsze Twoja decyzja.</strong>",
"Is this still a yes? Shed it, or keep it with one line on why. We'll quote you next time. <strong>“Just in case” is allowed.</strong> It reads worse the second time.": "Czy to nadal tak? Puść to albo zachowaj z jednym zdaniem dlaczego. Następnym razem Ci to zacytujemy. <strong>„Na wszelki wypadek” jest dozwolone.</strong> Za drugim razem brzmi gorzej.",
"Watch the number go up.": "Patrz, jak rośnie liczba.",
"Every shed adds to your total, and to what you've freed up if it had a price. Miss a week and nothing explodes. <strong>Miss a month and we'll mention it.</strong>": "Każde puszczenie zwiększa Twój wynik i to, co uwolniłeś, jeśli miało cenę. Opuść tydzień, a nic się nie stanie. <strong>Opuść miesiąc, a wspomnimy o tym.</strong>",
"Shedding unlocks new machines: at 3, 10, 25 things, and then streaks. Then make it yours with a nameplate, a light and a cut style. <strong>Brass is for the long haul.</strong>": "Puszczanie odblokowuje nowe maszyny: przy 3, 10, 25 rzeczach, a potem seriach. Potem spersonalizuj ją tabliczką, światłem i stylem cięcia. <strong>Brass jest na długi dystans.</strong>",
"Earn your shredder.": "Zasłuż na swoją niszczarkę.",
"Where everyone starts.": "Tu każdy zaczyna.",
"Opens full screen from your home screen, works offline, and <strong>is the only way to get reminders on an iPhone.</strong>": "Otwiera się na pełnym ekranie z ekranu głównego, działa offline i <strong>to jedyny sposób na przypomnienia na iPhonie.</strong>",
"Shedly works best installed.": "Shedly działa najlepiej po zainstalowaniu.",
