"Erase your list, history and profile from this device? This can't be undone.": "Usunąć listę, historię i profil z tego urządzenia? Nie można tego cofnąć.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Twoja lista jest przechowywana na tym urządzeniu, a także daty przypomnień, jeśli są włączone. Eksport daje kopię; usunięcie kasuje ją stąd.",
"Help test Shedly": "Pomóż testować Shedly",
