"Read the testing notes": "Przeczytaj notatki testowe",
"What we see": "Co widzimy",
"What we never see": "Czego nigdy nie widzimy",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Z jakich ekranów i przycisków korzystasz, Twoja seria w przedziałach oraz nagrania z ukrytym tekstem.",
"Item names, prices, dates, notes, your name or anything you type.": "Nazwy pozycji, ceny, daty, notatki, Twoje imię ani nic, co wpiszesz.",
"Thank you. You're helping us make it better.": "Dziękujemy. Pomagasz nam to ulepszyć.",
"Count me in": "Zapisz mnie",
"Maybe later": "Może później",
"Not for me": "Nie dla mnie",
"You can change this any time in You.": "Możesz to zmienić w dowolnym momencie w Ty.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens help, which get in the way, and where people get stuck.": "Należysz do pierwszych osób, które wypróbowują Shedly. <strong>Udostępnianie anonimowych danych o użyciu to najszybszy sposób, by go ulepszyć.</strong> Pokazuje nam, które ekrany pomagają, które przeszkadzają i gdzie ludzie utykają.",
"Looking back": "Spojrzenie wstecz",
"Don't ask about this one": "Nie pytaj o to więcej",
"Not at all": "Wcale",
"A bit": "Trochę",
"Yes, bring it back": "Tak, przywróć",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "Powiadomienia są zablokowane. Zezwól na nie dla Shedly w ustawieniach telefonu.",
"Couldn't turn reminders on. Try again.": "Nie udało się włączyć przypomnień. Spróbuj ponownie.",
"Reminders are on.": "Przypomnienia włączone.",
"Reminders are off.": "Przypomnienia wyłączone.",
"Turn reminders on": "Włącz przypomnienia",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Na iPhonie dodaj Shedly do ekranu początkowego, a następnie otwórz stamtąd.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Ta przeglądarka nie może wysyłać przypomnień. Spróbuj Chrome na Androidzie lub Safari na iPhonie.",
"Item reminders": "Przypomnienia o pozycjach",
"Deadline reminders": "Przypomnienia o terminach",
"For items with a date: a week, three days and one day before.": "Dla pozycji z datą: tydzień, trzy dni i dzień wcześniej.",
"Sunday evening, when this week's shed is due.": "W niedzielę wieczorem, gdy zbliża się termin tygodniowego puszczenia.",
"At most once a month, for items untouched for 30 days or more.": "Najwyżej raz w miesiącu, dla pozycji nietkniętych od 30 dni lub dłużej.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "W niedzielę po południu, tylko gdy masz serię co najmniej dwóch tygodni.",
"Show item names": "Pokaż nazwy pozycji",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Wyłączone: przypomnienie mówi „Pozycja wkrótce się kończy” zamiast podawać nazwę, więc ekran blokady pozostaje prywatny.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Przypomnienia są wysyłane przez usługę przypomnień Shedly. Otrzymuje ona tylko daty przypomnień i Twoje wybory włącz/wyłącz, a nazw pozycji nigdy, chyba że włączysz nazwy.",
"Off. Nothing is sent until you turn reminders on.": "Wyłączone. Nic nie jest wysyłane, dopóki nie włączysz przypomnień.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Godziny ciszy: nic między 21:00 a 8:00. Najwyżej jedno przypomnienie dziennie i około dwóch tygodniowo.",
"Notifications is where you pick which deadlines to hear about, and when.": "W Powiadomieniach wybierasz, o których terminach chcesz słyszeć i kiedy.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Pozycje z datą mogą przypomnieć o sobie przed końcem. Włącz to w Ty → Powiadomienia.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Chcesz dostać sygnał, zanim to się skończy? Ustaw przypomnienia w Ty → Powiadomienia.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Twoja lista jest pełna. Puść jedną, by zrobić miejsce, albo zaimportuj wyciąg bankowy w Ty → Import.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Wszystko z datą w ciągu najbliższych 30 dni ląduje tutaj, razem z kosztem.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Ta linijka pod tytułem to Shedly, które coś zauważa. To sugestia, nigdy reguła.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Każda niszczarka jest zdobywana. Dotknij swojej, by zmienić tabliczkę, światło, cięcie i dźwięk.",
"Your device asks for reduced motion, so shredding is instant.": "Twoje urządzenie prosi o ograniczenie ruchu, więc niszczenie jest natychmiastowe.",
"Rare shred. Gold ones turn up now and then.": "Rzadkie zniszczenie. Złote trafiają się od czasu do czasu.",
"Copied. Paste it anywhere.": "Skopiowano. Wklej gdziekolwiek.",
"Image saved.": "Obraz zapisany.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Wklej listę lub otwórz plik CSV z wyciągiem bankowym. Jest odczytywany na tym urządzeniu i nigdy nie jest przesyłany.",
"List or CSV to import": "Lista lub CSV do zaimportowania",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Po jednej w wierszu:\nNetflix 15 €/mies.\nKarnet na siłownię 30 €/mies.\nPaszport wygasa za 3 tygodnie\n\nlub wklej wiersze z CSV z banku",
"Or open a file: ": "Albo otwórz plik: ",
