"Got it, start listening": "Jasne, zacznij słuchać",
"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "Mikrofon jest wyłączony dla Shedly. Włącz go w ustawieniach telefonu lub przeglądarki.",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never receives or keeps the audio.": "Dyktowanie korzysta z wbudowanej usługi rozpoznawania mowy telefonu. Na większości telefonów oznacza to, że Twój głos jest wysyłany do Apple lub Google i zamieniany na tekst. Shedly nigdy nie otrzymuje ani nie przechowuje nagrania.",
"Type it like you'd say it.": "Wpisz to tak, jak byś powiedział.",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "Pisz naturalnie: „Netflix 15 €/mies.”, „Amazon kończy się w połowie przyszłego miesiąca”, „Paszport wygasa za 3 tygodnie”.",
