"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Udostępnia, z jakich ekranów i przycisków korzystasz, i nagrywa wygląd ekranów z ukrytym tekstem. Nazwy pozycji, ceny, notatki i wpisany tekst nigdy nie są wysyłane. Możesz to wyłączyć w dowolnym momencie.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Pokazuje dzisiejszą pogodę na niebie. Raz prosi o Twoją przybliżoną lokalizację, po czym wysyła ją zaokrągloną do ok. 10 km do Open-Meteo, aby sprawdzić pogodę. Nic więcej nie jest wysyłane.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Włącz przypomnienia w Ty, w Powiadomieniach. Wybierz terminy: tydzień, trzy dni i dzień przed. <strong>Cisza po 21:00 i nigdy więcej niż jedno dziennie.</strong>",
