"Hi, I'm Liam, the founder of Shedly.": "你好，我是 Liam，Shedly 的创始人。",
"Most to-do apps help you add things. Shedly helps you let go of them. Once a week it asks one question about one thing: is this still a yes?": "大多数待办应用帮你添加事项，Shedly 帮你放手。每周它只问一件事一个问题：这还是\"要\"吗？",
"Shed it and it goes through the shredder. Keep it and say why. That's the whole app.": "放手，它就进碎纸机。保留，就说说为什么。整个应用就这样。",
"No account, no email. Your list stays on this phone.": "无需账号，无需邮箱。你的清单只留在这部手机上。",
"Shedly is new, and I'd love your support and help to make it amazing. Tell me what works and what doesn't.": "Shedly 是新产品，我很希望得到你的支持和帮助，一起把它做得更棒。告诉我哪些好用，哪些不好用。",
"Founder, Shedly": "Shedly 创始人",
"Who's shedding?": "谁在放手？",
"So names and prices come out right. <strong>No account, no email.</strong>": "让名字和价格显示正确。<strong>无需账号，无需邮箱。</strong>",
"You can still type $15 or £12 on any item. Prices in different currencies stay separate.": "你仍可在任何事项上输入 $15 或 £12。不同货币的价格分开计算。",
"What should we call you?": "我们该怎么称呼你？",
"Pick your look.": "选择你的外观。",
"Dark or light, calm or loud. <strong>Tap one and the app changes right now.</strong>": "深色或浅色，沉静或鲜艳。<strong>点一下，应用立刻改变。</strong>",
"Weather in your sky.": "你的天空，实时天气。",
"Rain, sun, snow and a real moon, matching what's outside. <strong>Totally optional.</strong>": "雨、阳光、雪和真实的月亮，与窗外一致。<strong>完全可选。</strong>",
"Show today's weather in the sky": "在天空中显示今日天气",
"Show today's weather": "显示今日天气",
"Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "只会请求一次你的大致位置，并将其取整到约 10 公里后发送给 Open-Meteo 查询天气。不会发送其他任何内容。",
"Hear about it before it ends.": "在到期之前收到提醒。",
"A quiet nudge a week, three days and a day before something ends. <strong>Quiet after 9 pm, never more than one a day.</strong>": "在到期前一周、三天和一天轻轻提醒你。<strong>晚上 9 点后静音，每天最多一条。</strong>",
"Remind me before things end": "到期前提醒我",
"Your phone will ask for permission. You choose which items remind you, in You → Notifications.": "手机会请求权限。你可以在 我的 → 通知 中选择哪些事项提醒你。",
"Tap, or just swipe.": "点按，或直接滑动。",
"Flick left or right to go from Review to List, Shed and You. <strong>The tabs at the bottom still work either way.</strong>": "向左或向右滑动，即可从回顾切换到清单、放手和我的。<strong>底部标签依然可用。</strong>",
"Swipe between screens": "在屏幕间滑动切换",
"Turn it off any time in You.": "随时可在\"我的\"中关闭。",
"Without": "不使用",
"With swiping": "使用滑动",
"Your list stays on this phone. No account, no email. <strong>Help us test Shedly if you like.</strong>": "你的清单只留在这部手机上。无需账号，无需邮箱。<strong>如果愿意，欢迎帮我们测试 Shedly。</strong>",
"Share anonymous usage": "分享匿名使用数据",
"Share anonymous usage (testing)": "分享匿名使用数据（测试）",
"Records which screens and buttons you use, with all text hidden. Item names, prices and notes are never sent. Export or erase everything any time in You.": "记录你使用了哪些界面和按钮，所有文字均被隐藏。事项名称、价格和备注绝不会被发送。你可随时在\"我的\"中导出或清除全部数据。",
"Four screens. One swipe.": "四个界面，一次滑动。",
"Review is your weekly question, List is everything you've said yes to, Shed is your total and your machines, You is settings. <strong>Switch on swiping in You and flick between them.</strong>": "回顾是你的每周一问，清单是你答应过的一切，放手是你的总数和碎纸机，我的是设置。<strong>在\"我的\"中开启滑动，即可在它们之间切换。</strong>",
"A to-do list that gets shorter.": "一份越来越短的待办清单。",
"Every other app helps you add things. Shedly helps you let go of one. <strong>Once a week.</strong> That's the whole trick.": "其他应用都帮你添加事项，Shedly 帮你放下一件。<strong>每周一次。</strong>就这么简单。",
"Once a week, one question.": "每周一次，一个问题。",
"Add anything you've said yes to: tasks, meetings, subscriptions. Put a price on it and Shedly does the sums. <strong>Yes, even that one you forgot about.</strong>": "添加你答应过的一切：任务、会议、订阅。标上价格，Shedly 帮你算账。<strong>对，连你忘掉的那个也算。</strong>",
"It notices things.": "它会留意细节。",
"Renewals coming up, what each use really costs, and a line when you've kept something again and again. <strong>Never a rule. Always your call.</strong>": "即将续订的项目、每次使用的真实成本，以及你一再保留某事时的提示。<strong>从不强制，永远由你决定。</strong>",
"Is this still a yes? Shed it, or keep it with one line on why. We'll quote you next time. <strong>“Just in case” is allowed.</strong> It reads worse the second time.": "这还是\"要\"吗？放手，或写一句理由保留。下次我们会引用你的话。<strong>\"以防万一\"是允许的。</strong>不过第二次读起来就没那么好听了。",
"Watch the number go up.": "看着数字不断上涨。",
"Every shed adds to your total, and to what you've freed up if it had a price. Miss a week and nothing explodes. <strong>Miss a month and we'll mention it.</strong>": "每次放手都会累加到你的总数，以及（如果有价格）你节省下来的金额。错过一周，什么都不会发生。<strong>错过一个月，我们会提一句。</strong>",
"Shedding unlocks new machines: at 3, 10, 25 things, and then streaks. Then make it yours with a nameplate, a light and a cut style. <strong>Brass is for the long haul.</strong>": "放手会解锁新的碎纸机：放手 3、10、25 件事后，之后靠连续记录。然后用铭牌、指示灯和切割方式把它变成你的。<strong>Brass 属于长跑者。</strong>",
"Earn your shredder.": "赢得你的碎纸机。",
"Where everyone starts.": "每个人的起点。",
"Opens full screen from your home screen, works offline, and <strong>is the only way to get reminders on an iPhone.</strong>": "从主屏幕全屏打开，离线可用，并且<strong>是在 iPhone 上收到提醒的唯一方式。</strong>",
"Shedly works best installed.": "安装后 Shedly 体验最佳。",
