"Unlimited items": "不限事项数量",
"Full graveyard, with search": "完整墓地，可搜索",
"Import more than 15 at once": "一次导入超过 15 项",
"Sync across devices (coming)": "跨设备同步（即将推出）",
"Year in review is part of Plus. Preview Plus below.": "年度回顾属于 Plus。可在下方预览 Plus。",
"Search what you've shed": "搜索你放手过的事项",
