"Erase your list, history and profile from this device? This can't be undone.": "要从此设备清除你的清单、历史和个人资料吗？此操作无法撤销。",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "你的清单保存在此设备上；如果开启了提醒，提醒日期也会保存。导出会给你一份副本；清除会将其从这里删除。",
"Help test Shedly": "帮助测试 Shedly",
"Testing notes": "测试说明",
"Read the testing notes": "阅读测试说明",
"What we see": "我们能看到什么",
"What we never see": "我们绝不会看到什么",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "你使用了哪些界面和按钮、你的连续记录（以区间表示），以及隐藏所有文字的录屏。",
"Item names, prices, dates, notes, your name or anything you type.": "事项名称、价格、日期、备注、你的姓名，或你输入的任何内容。",
"Thank you. You're helping us make it better.": "谢谢你，你正在帮我们把它做得更好。",
"Count me in": "算我一个",
"Maybe later": "以后再说",
"Not for me": "不适合我",
"You can change this any time in You.": "你随时可以在\"我的\"中更改。",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens help, which get in the way, and where people get stuck.": "你是最早试用 Shedly 的人之一。<strong>分享匿名使用数据是让它变得更好的最快方式。</strong>它能让我们看到哪些界面有帮助、哪些碍事，以及大家在哪里卡住。",
"Looking back": "回头看看",
"Don't ask about this one": "不再询问这一项",
"Not at all": "完全不会",
"A bit": "有一点",
"Yes, bring it back": "会，把它找回来",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "通知已被屏蔽。请在手机设置中允许 Shedly 发送通知。",
"Couldn't turn reminders on. Try again.": "无法开启提醒。请再试一次。",
"Reminders are on.": "提醒已开启。",
"Reminders are off.": "提醒已关闭。",
"Turn reminders on": "开启提醒",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "在 iPhone 上，请先将 Shedly 添加到主屏幕，然后从那里打开。",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "此浏览器无法发送提醒。请在安卓上试试 Chrome，或在 iPhone 上试试 Safari。",
"Item reminders": "事项提醒",
"Deadline reminders": "截止提醒",
"For items with a date: a week, three days and one day before.": "针对有日期的事项：提前一周、三天和一天。",
"Sunday evening, when this week's shed is due.": "周日晚上，本周放手的时间到了。",
"At most once a month, for items untouched for 30 days or more.": "每月最多一次，针对 30 天或更久未动过的事项。",
"Sunday afternoon, only once you have a streak of two weeks or more.": "周日下午，仅在你的连续记录达到两周或以上时。",
"Show item names": "显示事项名称",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "关闭时：提醒只会显示\"有事项即将到期\"而不显示名称，锁屏因此保持私密。",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "提醒通过 Shedly 的提醒服务发送。它只会收到提醒日期和你的开关选择，除非你开启显示名称，否则绝不会收到事项名称。",
"Off. Nothing is sent until you turn reminders on.": "已关闭。在你开启提醒之前不会发送任何内容。",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "静音时段：晚上 9 点至早上 8 点不发送。每天最多一条提醒，每周大约两条。",
"Notifications is where you pick which deadlines to hear about, and when.": "在\"通知\"中，你可以选择要收到哪些截止提醒，以及何时收到。",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "有日期的事项可以在到期前提醒你。请在 我的 → 通知 中开启。",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "想在到期前收到提醒吗？请在 我的 → 通知 中设置提醒。",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "你的清单已满。放手一项腾出空间，或在 我的 → 导入 中导入银行对账单。",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "未来 30 天内有日期的事项都会出现在这里，并显示它会花你多少钱。",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "标题下的那行字是 Shedly 注意到了某件事。它只是提醒，绝不是规定。",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "每台碎纸机都是赢来的。点按你的碎纸机即可更改铭牌、指示灯、切割方式和声音。",
"Your device asks for reduced motion, so shredding is instant.": "你的设备开启了减少动态效果，所以碎纸是即时完成的。",
"Rare shred. Gold ones turn up now and then.": "稀有碎纸。偶尔会出现金色的。",
"Copied. Paste it anywhere.": "已复制。可粘贴到任何地方。",
"Image saved.": "图片已保存。",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "粘贴一份清单，或打开银行对账单 CSV。它只在此设备上读取，绝不会上传。",
"List or CSV to import": "要导入的清单或 CSV",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "每行一项：\nNetflix 15 欧元/月\n健身房会员 30 欧元/月\n护照 3 周后到期\n\n或粘贴银行 CSV 中的行",
"Or open a file: ": "或打开文件： ",
"Choose a file": "选择文件",
"Continue": "继续",
"Find things to review": "查找待回顾的事项",
"Dictate an item": "语音输入事项",
"Dictation": "语音输入",
"Got it, start listening": "知道了，开始聆听",
"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "Shedly 的麦克风已关闭。请在手机或浏览器设置中开启。",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never receives or keeps the audio.": "语音输入使用手机自带的语音服务。在大多数手机上，这意味着你的声音会发送给 Apple 或 Google 转为文字。Shedly 绝不会接收或保存音频。",
"Type it like you'd say it.": "像说话一样输入即可。",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "自然地输入即可：\"Netflix 15 欧元/月\"、\"Amazon 下个月中旬到期\"、\"护照 3 周后到期\"。",
