"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "分享你使用了哪些界面和按钮，并录制隐藏所有文字的界面外观。事项名称、价格、备注和输入的文字绝不会被发送。可随时关闭。",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "在天空中显示今日天气。只会请求一次你的大致位置，并将其取整到约 10 公里后发送给 Open-Meteo 查询天气。不会发送其他任何内容。",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "在\"我的\"→\"通知\"中开启提醒。选择你想要的截止提醒：提前一周、三天和一天。<strong>晚上 9 点后静音，每天最多一条。</strong>",
