"Clean lines, clinical stare. Judges your spelling, quietly.": "线条干净，目光冷峻。默默评判你的拼写。",
"Lives for Monday piles. Gets loud about it.": "为周一的那堆纸而活，还会为此大声抗议。",
"Built to last. Has never met a subscription it liked.": "经久耐用。从没喜欢过任何一个订阅。",
