"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Buburahin nito ang listahan, kasaysayan, mga makina, streak, pangalan, bansa at mga setting mo sa device na ito, at magsisimulang muli ang Shedly na parang bagong install. Hindi na ito mababawi.",
