"Tap <b>Install app</b> or <b>Add to Home screen</b>": "Pindutin ang <b>Install app</b> o <b>Add to Home screen</b>",
"Safari: Share, then Add to Home Screen": "Safari: Share, tapos Add to Home Screen",
