"Erase your list, history and profile from this device? This can't be undone.": "Buburahin ang listahan, kasaysayan at profile mo sa device na ito? Hindi na ito mababawi.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Nakaimbak sa device na ito ang listahan mo, pati ang mga petsa ng paalala kung naka-on ang mga paalala. Ang export ay magbibigay ng kopya; ang erase ay mag-aalis nito rito.",
"Help test Shedly": "Tulungang subukan ang Shedly",
"Testing notes": "Mga tala sa pagsubok",
"Read the testing notes": "Basahin ang mga tala sa pagsubok",
"What we see": "Ang nakikita namin",
"What we never see": "Ang hindi namin nakikita",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Kung aling mga screen at button ang ginagamit mo, ang streak mo sa mga saklaw, at mga recording na nakatago ang lahat ng teksto.",
"Item names, prices, dates, notes, your name or anything you type.": "Mga pangalan ng item, presyo, petsa, tala, pangalan mo o anumang tina-type mo.",
"Thank you. You're helping us make it better.": "Salamat. Tinutulungan mo kaming pagandahin ito.",
"Count me in": "Isali ako",
"Maybe later": "Baka mamaya",
"Not for me": "Hindi para sa akin",
"You can change this any time in You.": "Maaari mo itong baguhin anumang oras sa Ikaw.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens help, which get in the way, and where people get stuck.": "Isa ka sa mga unang sumubok ng Shedly. <strong>Ang pagbabahagi ng anonymous na paggamit ang pinakamabilis na paraan para pagandahin ito.</strong> Ipinapakita nito kung aling mga screen ang nakakatulong, alin ang nakakaabala, at kung saan nahihirapan ang mga tao.",
"Looking back": "Pagbabalik-tanaw",
"Don't ask about this one": "Huwag nang itanong ito",
"Not at all": "Hindi talaga",
"A bit": "Kaunti",
"Yes, bring it back": "Oo, ibalik ito",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "Naka-block ang mga abiso. Payagan ito para sa Shedly sa settings ng phone mo.",
"Couldn't turn reminders on. Try again.": "Hindi nabuksan ang mga paalala. Subukan muli.",
"Reminders are on.": "Naka-on ang mga paalala.",
"Reminders are off.": "Naka-off ang mga paalala.",
"Turn reminders on": "I-on ang mga paalala",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Sa iPhone, idagdag ang Shedly sa Home Screen, saka buksan mula roon.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Hindi makapagpadala ng paalala ang browser na ito. Subukan ang Chrome sa Android, o Safari sa iPhone.",
"Item reminders": "Mga paalala sa item",
"Deadline reminders": "Mga paalala sa deadline",
"For items with a date: a week, three days and one day before.": "Para sa mga item na may petsa: isang linggo, tatlong araw at isang araw bago.",
"Sunday evening, when this week's shed is due.": "Linggo ng gabi, kapag dapat nang bitawan ang para sa linggong ito.",
"At most once a month, for items untouched for 30 days or more.": "Hindi hihigit sa isang beses kada buwan, para sa mga item na hindi nagalaw nang 30 araw o higit pa.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "Linggo ng hapon, kapag may streak ka lang na dalawang linggo o higit pa.",
"Show item names": "Ipakita ang mga pangalan ng item",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Naka-off: sasabihin ng paalala na “Malapit nang matapos ang isang item” sa halip na pangalanan ito, kaya pribado ang lock screen.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Ipinapadala ang mga paalala sa pamamagitan ng reminder service ng Shedly. Mga petsa ng paalala at ang on/off na pinili mo lang ang natatanggap nito, at hindi kailanman ang mga pangalan ng item maliban kung i-on mo ang mga pangalan.",
"Off. Nothing is sent until you turn reminders on.": "Naka-off. Walang ipinapadala hangga't hindi mo ino-on ang mga paalala.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Tahimik na oras: walang ipapadala mula 9 pm hanggang 8 am. Hindi hihigit sa isang paalala kada araw, at mga dalawa kada linggo.",
"Notifications is where you pick which deadlines to hear about, and when.": "Sa Mga abiso mo pinipili kung aling mga deadline ang gusto mong malaman, at kailan.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Ang mga item na may petsa ay maaaring magpaalala bago matapos. I-on iyon sa Ikaw → Mga abiso.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Gusto mo ng paunang abiso bago ito matapos? I-set ang mga paalala sa Ikaw → Mga abiso.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Puno na ang listahan mo. Bitawan ang isa para magkaroon ng espasyo, o mag-import ng bank statement sa Ikaw → Import.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Dito mapupunta ang anumang may petsa sa susunod na 30 araw, kasama ang magiging gastos nito.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Ang linya sa ilalim ng pamagat ay may napansin ang Shedly. Paalala lang ito, hindi kailanman patakaran.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Bawat shredder ay napapanalunan. Pindutin ang sa iyo para baguhin ang nameplate, ilaw, hiwa at tunog.",
"Your device asks for reduced motion, so shredding is instant.": "Humihiling ang device mo ng nabawasang galaw, kaya agad ang pagpunit.",
"Rare shred. Gold ones turn up now and then.": "Bihirang hiwa. Paminsan-minsan may lumalabas na ginto.",
"Copied. Paste it anywhere.": "Nakopya na. I-paste kahit saan.",
"Image saved.": "Na-save ang larawan.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Mag-paste ng listahan, o magbukas ng bank statement CSV. Binabasa ito sa device na ito at hindi kailanman ina-upload.",
"List or CSV to import": "Listahan o CSV na i-import",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Isa kada linya:\nNetflix €15/buwan\nGym membership €30/buwan\nMag-e-expire ang passport sa loob ng 3 linggo\n\no mag-paste ng mga hilera mula sa CSV ng bangko mo",
"Or open a file: ": "O magbukas ng file: ",
"Choose a file": "Pumili ng file",
"Continue": "Magpatuloy",
"Find things to review": "Maghanap ng susuriin",
"Dictate an item": "Idikta ang item",
"Dictation": "Dikta",
"Got it, start listening": "Sige, simulan ang pakikinig",
"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "Naka-off ang mikropono para sa Shedly. I-on ito sa settings ng phone o browser mo.",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never receives or keeps the audio.": "Gumagamit ang dikta ng sariling speech service ng phone mo. Sa karamihan ng phone, nangangahulugan itong ipinapadala ang boses mo sa Apple o Google para gawing teksto. Hindi kailanman natatanggap o iniimbak ng Shedly ang audio.",
"Type it like you'd say it.": "I-type ito na parang sinasabi mo.",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "Mag-type nang natural: “Netflix €15/buwan”, “Matatapos ang Amazon sa kalagitnaan ng susunod na buwan”, “Mag-e-expire ang passport sa loob ng 3 linggo”.",
