"Installed. Find Shedly on your home screen.": "Na-install na. Hanapin ang Shedly sa home screen mo.",
"Swipe left or right anywhere on Review, List, Shed or You to move to the next screen.": "Mag-swipe pakaliwa o pakanan kahit saan sa Suriin, Listahan, Bitawan o Ikaw para lumipat sa susunod na screen.",
