"Dictate": "Idikta",
"Make it yours": "Gawin itong iyo",
"Shown on your weekly review. Stays on this device.": "Ipinapakita sa lingguhang pagsusuri mo. Nananatili sa device na ito.",
"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Nagbabahagi kung aling mga screen at button ang ginagamit mo, at nagre-record kung ano ang itsura ng mga screen na nakatago ang lahat ng teksto. Hindi kailanman ipinapadala ang mga pangalan ng item, presyo, tala at tina-type na teksto. Patayin anumang oras.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Ipinapakita ang panahon ngayon sa langit. Hihingin nang isang beses ang tinatayang lokasyon mo, saka ipapadala ito sa Open-Meteo na naka-round sa mga 10 km para tingnan ang panahon. Wala nang iba pang ipinapadala.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "I-on ang mga paalala sa Ikaw, sa ilalim ng Mga abiso. Piliin ang mga deadline na gusto mo: isang linggo, tatlong araw at isang araw bago. <strong>Tahimik pagkatapos ng 9 pm, at hindi hihigit sa isa kada araw.</strong>",
