"Everything you've said yes to, costliest and most ignored first.": "Lahat ng inoo-an mo, pinakamahal at pinakanalimutan ang una.",
"Nothing yet. What are you paying attention to right now?": "Wala pa. Ano ang pinagtutuunan mo ng pansin ngayon?",
"On. Location rounded to about 10 km.": "Naka-on. Naka-round ang lokasyon sa mga 10 km.",
