"Fiery": "Maapoy",
"Eager": "Sabik",
"Patient": "Matiyaga",
"Slow": "Mabagal",
"Dazzling": "Nakasisilaw",
"Grand": "Marangya",
"Clean lines, clinical stare. Judges your spelling, quietly.": "Malinis ang linya, klinikal ang tingin. Tahimik na humuhusga sa spelling mo.",
"Lives for Monday piles. Gets loud about it.": "Buhay niya ang mga tambak tuwing Lunes. Maingay tungkol dito.",
"Built to last. Has never met a subscription it liked.": "Ginawa para tumagal. Hindi kailanman nagustuhan ang anumang subscription.",
"Only comes out for a proper plan.": "Lumalabas lang para sa maayos na plano.",
"Knows exactly what you're avoiding.": "Alam nito kung ano ang iniiwasan mo.",
"Runs warm and hates being rushed.": "Mainit tumakbo at ayaw minamadali.",
"Weathered, patient, a little smug about it.": "Kinakalawang, matiyaga, at medyo mayabang tungkol dito.",
"Polished steel. You earned the shine.": "Pinakintab na bakal. Pinaghirapan mo ang kislap.",
"The one you started with. Never once complained.": "Ang una mong ginamit. Hindi kailanman nagreklamo.",
"Shed 3 things to meet it.": "Bitawan ang 3 bagay para makilala ito.",
"Shed 10 things. It's already warming up.": "Bitawan ang 10 bagay. Nag-iinit na ito.",
"Shed 3 subscriptions to wake it up.": "Bitawan ang 3 subscription para magising ito.",
"Shed 50 things. It only trusts a plan.": "Bitawan ang 50 bagay. Plano lang ang pinagkakatiwalaan nito.",
"Shed 100 things. It has been watching.": "Bitawan ang 100 bagay. Matagal na itong nagmamasid.",
"Keep a 4-week streak to light it.": "Panatilihin ang 4-linggong streak para mailawan ito.",
"Keep an 8-week streak. Good things take time.": "Panatilihin ang 8-linggong streak. Mabagal ang mabubuting bagay.",
"Free 1,000 a year to polish it.": "Magpalaya ng 1,000 kada taon para mapakintab ito.",
"Shed 5 things on a Sunday. Good things take time.": "Bitawan ang 5 bagay tuwing Linggo. Mabagal ang mabubuting bagay.",
