"Wipe everything?": "Papason ang tanan?",
"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Papason niini ang imong listahan, kasaysayan, mga makina, streak, ngalan, nasud ug mga setting niining device, ug magsugod pag-usab ang Shedly nga daw bag-o lang na-install. Dili na kini mabalik.",
