"Import more than 15 at once": "Mag-import og kapin sa 15 sa usa ka higayon",
"Sync across devices (coming)": "Sync sa lainlaing device (umaabot)",
"Year in review is part of Plus. Preview Plus below.": "Bahin sa Plus ang Year in review. I-preview ang Plus sa ubos.",
"Search what you've shed": "Pangitaa ang imong nabuhi",
"Export my data": "I-export akong data",
"Erase everything": "Papasa ang tanan",
"Erase your list, history and profile from this device? This can't be undone.": "Papason ang imong listahan, kasaysayan ug profile niining device? Dili na kini mabalik.",
"Your list is stored on this device, plus reminder dates if reminders are on. Export gives you a copy; erase removes it from here.": "Gitipigan niining device ang imong listahan, ingon man ang mga petsa sa pahinumdom kung naka-on ang mga pahinumdom. Ang export mohatag og kopya; ang erase mopapas niini dinhi.",
"Help test Shedly": "Tabangi pagsulay ang Shedly",
"Testing notes": "Mga nota sa pagsulay",
"Read the testing notes": "Basaha ang mga nota sa pagsulay",
"What we see": "Ang makita namo",
"What we never see": "Ang dili namo makita",
"Which screens and buttons you use, your streak in ranges, and recordings with all text hidden.": "Unsang mga screen ug button ang imong gigamit, ang imong streak sa mga range, ug mga recording nga tago ang tanang teksto.",
"Item names, prices, dates, notes, your name or anything you type.": "Mga ngalan sa item, presyo, petsa, nota, imong ngalan o bisan unsa nga imong i-type.",
"Thank you. You're helping us make it better.": "Salamat. Gitabangan nimo kami nga mapaayo kini.",
"Count me in": "Apil ko",
"Maybe later": "Basin sunod",
"Not for me": "Dili para nako",
"You can change this any time in You.": "Mahimo nimo kining usbon bisan kanus-a sa Ikaw.",
"You're one of the first people to try Shedly. <strong>Sharing anonymous usage is the fastest way to make it better.</strong> It shows us which screens help, which get in the way, and where people get stuck.": "Usa ka sa unang mga nagsulay sa Shedly. <strong>Ang pagpaambit sa anonymous nga paggamit mao ang pinakadali nga paagi aron mapaayo kini.</strong> Gipakita niini kung unsang mga screen ang makatabang, hain ang makabalda, ug asa nalisdan ang mga tawo.",
"Looking back": "Pagbalik-tan-aw",
"Don't ask about this one": "Ayaw na pangutana bahin niini",
"Not at all": "Dili gyud",
"A bit": "Gamay",
"Yes, bring it back": "Oo, ibalik kini",
"Notifications are blocked. Allow them for Shedly in your phone settings.": "Gi-block ang mga pahibalo. Tugoti kini para sa Shedly sa settings sa imong telepono.",
"Couldn't turn reminders on. Try again.": "Wala ma-on ang mga pahinumdom. Sulayi pag-usab.",
"Reminders are on.": "Naka-on ang mga pahinumdom.",
"Reminders are off.": "Naka-off ang mga pahinumdom.",
"Turn reminders on": "I-on ang mga pahinumdom",
"On iPhone, add Shedly to your Home Screen, then open it from there.": "Sa iPhone, idugang ang Shedly sa Home Screen, unya ablihi gikan didto.",
"This browser can't send reminders. Try Chrome on Android, or Safari on iPhone.": "Dili makapadala og pahinumdom kini nga browser. Sulayi ang Chrome sa Android, o Safari sa iPhone.",
"Item reminders": "Mga pahinumdom sa item",
"Deadline reminders": "Mga pahinumdom sa deadline",
"For items with a date: a week, three days and one day before.": "Para sa mga item nga naay petsa: usa ka semana, tulo ka adlaw ug usa ka adlaw sa dili pa.",
"Sunday evening, when this week's shed is due.": "Domingo sa gabii, kung panahon na sa pagbuhi karong semanaha.",
"At most once a month, for items untouched for 30 days or more.": "Dili molapas sa kausa matag bulan, para sa mga item nga wala gihikap sulod sa 30 ka adlaw o kapin pa.",
"Sunday afternoon, only once you have a streak of two weeks or more.": "Domingo sa hapon, kung naa ra kay streak nga duha ka semana o kapin pa.",
"Show item names": "Ipakita ang mga ngalan sa item",
"Off: a reminder says “An item is ending soon” rather than naming it, so the lock screen stays private.": "Naka-off: ang pahinumdom moingon nga “Hapit na mahurot ang usa ka item” imbes nga ngalanan kini, aron pribado ang lock screen.",
"Reminders are sent through Shedly's reminder service. It only gets reminder dates and your on/off choices, and never item names unless you turn names on.": "Ipadala ang mga pahinumdom pinaagi sa reminder service sa Shedly. Mga petsa sa pahinumdom ug imong on/off nga pagpili ra ang madawat niini, ug dili gayod ang mga ngalan sa item gawas kung i-on nimo ang mga ngalan.",
"Off. Nothing is sent until you turn reminders on.": "Naka-off. Walay ipadala hangtod i-on nimo ang mga pahinumdom.",
"Quiet hours: nothing between 9 pm and 8 am. At most one reminder a day, and about two a week.": "Hilom nga oras: walay ipadala tali sa 9 pm ug 8 am. Dili molapas sa usa ka pahinumdom matag adlaw, ug mga duha matag semana.",
"Notifications is where you pick which deadlines to hear about, and when.": "Sa Mga pahibalo nimo pilion kung unsang mga deadline ang gusto nimo mahibaloan, ug kanus-a.",
"Items with a date can nudge you before they end. Turn that on under You → Notifications.": "Ang mga item nga naay petsa mahimong mopahinumdom sa dili pa mahurot. I-on kini sa Ikaw → Mga pahibalo.",
"Want a heads-up before this ends? Set reminders under You → Notifications.": "Gusto ka og pahibalo sa dili pa kini mahurot? I-set ang mga pahinumdom sa Ikaw → Mga pahibalo.",
"Your list is full. Shed one to make room, or bring a bank statement in under You → Import.": "Puno na ang imong listahan. Buhii ang usa aron mahimong lugar, o mag-import og bank statement sa Ikaw → Import.",
"Anything with a date in the next 30 days lands here, with what it will cost you.": "Dinhi mapunta ang bisan unsa nga naay petsa sa sunod nga 30 ka adlaw, uban sa gasto niini.",
"That line under the title is Shedly noticing something. It's a nudge, never a rule.": "Ang linya ilalom sa titulo mao ang Shedly nga naay namatikdan. Pahinumdom lang kini, dili gayod balaod.",
"Every shredder is earned. Tap yours to change the nameplate, light, cut and sound.": "Matag shredder makuha. Pislita ang imo aron usbon ang nameplate, suga, putol ug tunog.",
"Your device asks for reduced motion, so shredding is instant.": "Nangayo ang imong device og gamay nga lihok, mao nga dayon ang pagpunit.",
"Rare shred. Gold ones turn up now and then.": "Talagsaon nga pagpunit. Usahay naay mugawas nga bulawan.",
"Copied. Paste it anywhere.": "Na-kopya na. I-paste bisan asa.",
"Image saved.": "Na-save ang hulagway.",
"Paste a list, or open a bank statement CSV. It's read on this device and never uploaded.": "Mag-paste og listahan, o mag-abli og bank statement CSV. Gibasa kini niining device ug dili gayod i-upload.",
"List or CSV to import": "Listahan o CSV nga i-import",
"One per line:\nNetflix €15/mo\nGym membership €30/mo\nPassport expires in 3 weeks\n\nor paste rows from your bank's CSV": "Usa matag linya:\nNetflix €15/bulan\nGym membership €30/bulan\nMo-expire ang passport sa 3 ka semana\n\no mag-paste og mga laray gikan sa CSV sa imong bangko",
"Or open a file: ": "O mag-abli og file: ",
