"Microphone is off for Shedly. Turn it on in your phone or browser settings.": "Naka-off ang mikropono para sa Shedly. I-on kini sa settings sa imong telepono o browser.",
"Dictation uses your phone's own speech service. On most phones that means your voice is sent to Apple or Google to be turned into text. Shedly never receives or keeps the audio.": "Ang dikta migamit sa kaugalingong speech service sa imong telepono. Sa kadaghanang telepono, nagpasabot kini nga ipadala ang imong tingog sa Apple o Google aron himoong teksto. Dili gayod madawat o tipigan sa Shedly ang audio.",
"Type it like you'd say it.": "I-type kini sama sa imong isulti.",
"Type it naturally: “Netflix €15/mo”, “Amazon ends middle of next month”, “Passport expires in 3 weeks”.": "Mag-type nga natural: “Netflix €15/bulan”, “Mahurot ang Amazon sa tunga-tunga sa sunod bulan”, “Mo-expire ang passport sa 3 ka semana”.",
