"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Mopaambit kung unsang mga screen ug button ang imong gigamit, ug mag-record kung unsa ang hitsura sa mga screen nga tago ang tanang teksto. Dili gayod ipadala ang mga ngalan sa item, presyo, nota ug gi-type nga teksto. Patya bisan kanus-a.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Gipakita ang panahon karon sa langit. Mangayo kausa sa imong tantiya nga lokasyon, unya ipadala kini sa Open-Meteo nga gi-round sa mga 10 km aron tan-awon ang panahon. Walay lain nga ipadala.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "I-on ang mga pahinumdom sa Ikaw, ilalom sa Mga pahibalo. Pilia ang mga deadline nga gusto nimo: usa ka semana, tulo ka adlaw ug usa ka adlaw sa dili pa. <strong>Hilom human sa 9 pm, ug dili molapas sa usa matag adlaw.</strong>",
