"Add what you've said yes to: tasks, meetings, subscriptions. Tap a few to see how it works.": "Добавьте то, на что вы согласились: задачи, встречи, подписки. Нажмите на несколько, чтобы увидеть, как это работает.",
"+ Gym membership €30/mo": "+ Абонемент в спортзал 30 €/мес.",
