"Shown on your weekly review. Stays on this device.": "Показывается в вашем недельном обзоре. Остаётся на этом устройстве.",
"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Делится сведениями о том, какими экранами и кнопками вы пользуетесь, и записывает вид экранов с полностью скрытым текстом. Названия позиций, цены, заметки и введённый текст никогда не отправляются. Выключить можно в любой момент.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Показывает сегодняшнюю погоду в небе. Один раз запрашивает ваше примерное местоположение, затем отправляет его, округлённым до 10 км, в Open-Meteo, чтобы узнать погоду. Больше ничего не отправляется.",
"Turn on reminders in You, under Notifications. Pick the deadlines you want: a week, three days and one day before. <strong>Quiet after 9 pm, and never more than one a day.</strong>": "Включите напоминания в разделе «Вы», в «Уведомлениях». Выберите нужные сроки: за неделю, за три дня и за один день. <strong>Тишина после 21:00 и не больше одного в день.</strong>",
