"This deletes your list, history, machines, streak, name, country and settings from this device, then restarts Shedly as if you'd just installed it. It can't be undone.": "Це видалить із пристрою ваш список, історію, машини, серію, ім’я, країну й налаштування, а потім перезапустить Shedly, ніби його щойно встановили. Це неможливо скасувати.",
