"Snow at Christmas, hearts on Valentine's, falling leaves in autumn, and so on.": "Сніг на Різдво, сердечка на День святого Валентина, листя, що падає восени, тощо.",
"More colours unlock as you shed. Tap one to use it.": "Нові кольори відкриваються в міру відпускання. Торкніться кольору, щоб використати.",
