"Shares which screens and buttons you use, and records how screens look with all text hidden. Item names, prices, notes and typed text are never sent. Turn it off any time.": "Ділиться відомостями про те, якими екранами й кнопками ви користуєтеся, і записує вигляд екранів із повністю прихованим текстом. Назви позицій, ціни, нотатки та введений текст ніколи не надсилаються. Вимкнути можна будь-коли.",
"Shows today's weather in the sky. Asks for your approximate location once, then sends it rounded to about 10 km to Open-Meteo to look up the weather. Nothing else is sent.": "Показує сьогоднішню погоду в небі. Один раз запитує ваше приблизне місцезнаходження, потім надсилає його, округлене до 10 км, до Open-Meteo, щоб дізнатися погоду. Більше нічого не надсилається.",
